/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20121127-8","meetingId":"h24-cm11","date":"2012年11月27日","dateIso":"2012-11-27","committee":"建設委員会","time":"午前１０時００分～午後３時３０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１、附帯決議（案）","agenda":"の１、附帯決議（案）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと質問なんですけれども、２番の「以前にも２回の規約変更を行っているが」という、この中身を教えていただきたいのが一点と、もう一つ、１番目ですけれども「各特別区がより一層、自主性と独自性が発揮できる仕組みの構築を実現すべきである」という文言なんですけれども、これはそれぞれの区が独自にやっていくということをつくっていくべきだという意味で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-001"},{"speaker":"須藤委員","kind":"意見","question":"それから３番目については、「各区が直接」というのは、いわゆる都区制度が移管されたとき、将来的に清掃協議会は廃止するよと、一時的な連絡機関として持つものだよという話だったので、そのことを、あまり大っぴらに解散しろというようなことは言い切れないと思うので、こういう表現で、「各区が直接処理する方向で具体的に」というのは、各区が独自性を持った制度の方向性を決めなさい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"１番のところが、品川区だけが個別にできる仕組みでないということを確認させていただければ、賛同をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":8,"id":"exchange-003"},{"speaker":"須藤委員","kind":"質問・要望","question":"品川区だけ飛び出していって勝手に何かしようということではなくて、その心意気だけは品川区の中では残しておきたいということの意志を、昨日もお話ししたとおり示していきたいということでの決議文ということで、ご理解いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-004"}]},{"id":"topic-02","title":"平成２４年請願第１９号、武蔵小山駅周辺まちづくりへの住民参加を求める請願","agenda":"平成２４年請願第１９号、武蔵小山駅周辺まちづくりへの住民参加を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点で私がこの街並み誘導指針でお聞きしたいのは、どういう形でつくられたのか、区だけがつくってきたのか、ここには町会長、商店街には説明したということなんですけれども、私は本来であれば地域の中に協議会などをつくって、そのまちをどういうふうにしていくのかということで地域の方々と相談をしながら、長い間かけてこういうのはつくっていくべきものではないかと思うんですけれども。","respondent":"溝口都市開発課長","answer":"策定経緯といたしましては、繰り返しの説明になりますが、全く意見を聞かないというわけではなくて、住民アンケートですとか商店街のヒアリングといったものを重ねながらつくってきているものですので、そういったものの意見に沿った形でつくってきているものです。","voiceIndex":18,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"まちづくりビジョンの議事録を読んでいましたら、町会長１人の意見だけで決めるつもりはさらさらないという区の答弁があったんですけれども、そう言いながらも、実際に説明をして質疑があったのはこの自治会長会議だけであって、このまちの方々、この請願の中にもまちの人たちの意見を聞いてくださいと、そしてそれを計画に反映してくださいというのが一番の思いだと思うんですけれど、そういう点でいえば。","respondent":"溝口都市開発課長","answer":"今回、まちづくりビジョンおよび街並み誘導指針につきましては、対象区域が５６ヘクタール、武蔵小山の林試の森公園、また平塚小学校跡地まで含めた広い範囲を対象にした地域になっておりまして、そこの方たちを全員対象にした説明会というのはやっておりません。","voiceIndex":20,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"「人々の触れ合いを大切にする庶民のまち」というのが、区がとったアンケートの中で最も多いまちの人の声であり、「洗練された都会的なまち」は５.６％しかなくて最下位だということで、今回進めていくのはどちらかというと「人々の触れ合いを大切にする庶民的なまち」というよりは、「洗練された都会的なまち」というイメージのまちになっているのではないかというのが。","respondent":"溝口都市開発課長","answer":"４棟の建物につきましては、一応イメージとして、街並み誘導指針で出しています。詳しくは今後の計画の中で進んでいきますが、それをまちづくりのスカイラインの頂点として、ゆるやかに一般市街地につながっていく、そういった考え方を示しているものです。","voiceIndex":22,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この請願の中では、まちづくりビジョンと街並み誘導指針の内容について、区の責任において武蔵小山周辺住民に、丁寧な広報と複数回の説明、公聴会を開いてくださいという要望なんですけれども、これからでもぜひ、このまちづくりビジョンと誘導指針については、この地域の方すべての住民を対象にした説明会、そしてご意見を伺うという場をぜひ持つべきだと思うんですけれども。","respondent":"溝口都市開発課長","answer":"先ほどご説明したとおり、区民等への周知につきましては、区の広報およびホームページに掲載して、十分周知をしていますので、改めて説明会を開催するという考えはございません。","voiceIndex":24,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どうして説明会をされないんでしょうか。まちづくりのビジョンを地域の方に知っていただきたいというのは、区としてはないんでしょうか。","respondent":"溝口都市開発課長","answer":"区民の方へ知らせるために広報しながわという媒体がありますので、それを活用して皆様にご報告し、また全文が見たいということであればホームページで閲覧できるような形で、そういったものもあわせて広報で周知をしておりますので。","voiceIndex":26,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区がそんな思いを抱きながら、いいまちにしたいという思いで区としてつくっていく、そういう計画なわけですから、それをより多くの方に知っていただきたいというふうには、区としては思わないのかということを、先ほどお伺いしたんですね。知っていただきたいと思わないのか。","respondent":"溝口都市開発課長","answer":"知っていただきたいという思いで、広報しながわに掲載をしておりますし、ホームページでも公開しています。そういったもので行っているものです。","voiceIndex":28,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"知っていただきたいという思いがあることをはっきり伺って、とてもうれしく思っています。知っていただきたいと思いながら、広報とホームページで、じゃあ、地域のどれぐらいの方に知られているかというところでは、区としてはどういうふうに思われているんでしょうか。","respondent":"溝口都市開発課長","answer":"私どもといたしましては、これまでも品川区のさまざまなお知らせをしてきた広報しながわに掲載することで、十分皆さんに周知というのは図られているというふうに考えております。","voiceIndex":30,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一度、この街並み誘導指針をご存じですかということをどこかで聞いていただくなり、とっていただくなり、ぜひともしていただきたいと思います。そういうところで本当に区がこのまちづくりビジョン、街並み誘導指針を、この武蔵小山の地域の方皆さんに知っていただきたいということであれば、私はぜひとも説明会を開いていただきたいと、改めてお伺いします。","respondent":"溝口都市開発課長","answer":"あわせまして、今回の武蔵小山周辺地域のまちづくりビジョンおよび街並み誘導指針につきましては、まちづくりマスタープランでも位置づけて、現在パブリックコメント等も実施しておりますので、そういった中でもまた意見はお聞きできるというふうに考えているものです。","voiceIndex":32,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、これそのものを地域の方に、本当に関心が、あれだけ２日間にわたって説明会にたくさん来られるわけですから、そういう点でいえば、私、武蔵小山に住んでいる方って、本当に自分のまちを愛して、住みやすくて、すばらしい商店街もあり、そのまちに住み続けたいと思っている方が、本当にたくさんいらっしゃると思うんですね。","respondent":"片田都市環境事業部長","answer":"そういう方針をやはり区民の方と協働して、理解を求めて進めていくことが、これは確かにおっしゃるとおり大事なことだと思いますが、やはり説明会をやるということではなくて、区側が案として策定したものについては。","voiceIndex":34,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そういう点ではぜひともアンケートを、アンケートも生かされていないというのが地域の方の思いですから、アンケートをとってそれで終わりというのではなくて、またここに書かれているように自治会長、商店街、組合関係者、この関係者も営業されている一人ひとりの皆さんが本当に入っているのかどうかということも改めてお伺いしたいんですけれども。","respondent":"溝口都市開発課長","answer":"今回、アセスメントにつきましては、あくまでもそれぞれの計画する建築物の敷地に対してかけるものですので、４つあるからといって、４つまとめてアセスメントの対象になるというものではございません。","voiceIndex":36,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから本来であれば、これぐらいのものでもアセスメントの対象にすべきという改善がされるべきだと思うんですけれども、それが４つ合わさったときには必ずアセスメントの対象になるので、そういうところを求めていくことはできないものなのでしょうか。環境そのものにすごく大きな負荷になる、そういう開発になると思いますので、そこら辺のところをひとつお聞かせください。","respondent":"溝口都市開発課長","answer":"そのほかの地区についてはどのような建築物にされるのか、それは今後建物の計画が決まっていく中で、最終的にはすべて再開発事業というか、建物を建てていく中での検討になっていくというふうに考えておりますし、区といたしましても、自分のところの再開発地区だけでなく。","voiceIndex":38,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"アセスメントのことについては、建物の風環境とか日影とかはありますけれど、交通量予測というのもされるんでしょうか。そこのところをお聞かせいただきたいのが一つと。需要は十分あるということなんですけれど、これは何を根拠に需要が十分あると言われているのかお聞かせいただきたいと思います。","respondent":"溝口都市開発課長","answer":"需要につきましては、当然空室率とか、そういったものを踏まえながら、今回のパルム駅前地区については６４０戸の住宅が建てられるというふうに考えておりますので、そういったものは当然専門家であるディベロッパー、そういったものが中心になって需要予測等をしながら。","voiceIndex":40,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ディベロッパーは、地域のマンションの空室とかそういうものも調べているんでしょうか。","respondent":"溝口都市開発課長","answer":"当然需要のないところには再開発事業、またマンション開発といったものは起きないというふうに考えておりますので、今回のパルム駅前地区につきましては十分、立地条件等を勘案して６４０戸の住宅の建設は可能だというふうに、判断しているものです。","voiceIndex":42,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つは、街並み誘導指針を見ていて疑問に思ったのは、４棟の１４０メートル級の超高層に加えて、６０メートル、４５メートルの建物をつくっていくという複数の高層建築物群により、品川区の西の玄関口、荏原地区の中心核にふさわしい新たなスカイラインを形成するということなんですけれども、まちの方は、超高層は武蔵小山にはふさわしくないという声をたくさん聞くんですけれど。","respondent":"片田都市環境事業部長","answer":"ですから今回の基盤についても、先ほど委員からご質問がありましたように、交通量などの調査もやった中で、きちっとした整備をして計画の実現を目指していくというものですので、４棟ということについても、今後地域の方々がそういうまちづくりを進めていく上で、計画の妥当性。","voiceIndex":44,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これだけの高い建物をつくれば、ペイできないはずがないじゃないですか。まちの声を聞かないから、そういうふうな開発にどんどんどんどん進んでいくのではないかと私は思いますので、ぜひ地域の方が望んでいるように、街並み誘導指針もしっかりと、地域の方の合意が得られるような形で、説明会を開いていただきたいということを強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"共産党からいろいろな意見が出たんですけれども、やはり我々が子どものころ住んでいたまち、そして時代とともにどんどんと変化をしていくまちに、やはりその当時、その当時の愛着というものがあると思うんですね。ですから、今の武蔵小山、もしくはこの品川区の各まちすべてにおいて、その住民は今のまちに対して、それを守っていきたいと思っていると思うんです。その点、区のほうではどのように考えますか。","respondent":"溝口都市開発課長","answer":"ですから、そういった地域の課題を解決していく一つの手法として再開発事業というのがあると考えておりますので、そういった地域の課題、また地権者の方たちの思い、そういったものを踏まえながら、まちづくりは進めていきたいと考えております。","voiceIndex":47,"id":"exchange-020"},{"speaker":"木村委員","kind":"質問","question":"高いビルが建つということで、風害とかいろいろと問題があると思います。共産党の方々はそのようなことも言っておりますけれども、ビルの建て方、デザインのやり方によって、その風害を抑えることができる建て方があるということを聞いたことがありますけれども、そういうことはご存じでしょうか。そういうものが取り入れられるかどうか、お答えください。","respondent":"溝口都市開発課長","answer":"風害につきましては、委員ご指摘のようにさまざまな建物の形を、例えば角を丸くするですとか、ひさしを設けて、ビルに当たった風が下に行かないような工夫をするとか、そういったものがあるというのは私どもも承知しておりますし、当然今回計画する建物に際しては。","voiceIndex":51,"id":"exchange-021"},{"speaker":"木村委員","kind":"意見","question":"パルム商店街を中心に、一人でも多くの方々が住んでくれるというのは、やはり大変すばらしいと思います。そして武蔵小山のいいところ、よきものというのがあると思うんですね。そういう意味では、新しい開発をすることによって、そういうものを随所に残していくということは大変大事だと思っているんです。そういう計画があるかもお聞かせください。","respondent":"溝口都市開発課長","answer":"今回の武蔵小山パルム駅前地区につきましては、武蔵小山駅前、またパルム商店街の入口になっておりますので、当然今まで培ってきた、武蔵小山はアーケードのある商店街というのが一つの特徴だと考えています、そういったものを壊さないように。","voiceIndex":53,"id":"exchange-022"},{"speaker":"浅野委員","kind":"質問・要望","question":"その中で確認したいことが何点かありますので、それらについて教えていただければと思います。そういう意味では、地域全体で何とかしていっていただきたいという考えもあるようです。このようなことというのは、当てはまるかと思うんですけれども、区としての認識はどうお持ちなのか、改めてお伺いします。","respondent":"溝口都市開発課長","answer":"そういった中で各所有者の方、また使われている方の負担で直すというのは、非常に大変なことだと考えています。避難経路の件ですが、当然パルム駅前地区から平塚橋のほうの方々につきましては、当地区周辺を通って避難所に行かなければならない。","voiceIndex":55,"id":"exchange-023"},{"speaker":"浅野委員","kind":"質問","question":"その方もやはり長く住まれているということで、この地域に本当に愛着があるというんでしょうか、ずっと住み続けたいというふうに思っている方なんですね。そして、もう一つ危惧がありまして、この方が言われるに、やはり全体的な建替えという形をとっていただくのが一番いいというふうに考えているんですが、その中で心配しているのは、もしこの計画が頓挫したらどうなるか。","respondent":"溝口都市開発課長","answer":"防災に関する、まず地権者の意見ですが、木造住宅が密集している地域で、３・１１を契機に一体どういう形でまちづくりを進めていったらいいか、そういった意見も聞いていますし、住んでいても非常に危険でという話は聞いております。","voiceIndex":57,"id":"exchange-024"},{"speaker":"浅野委員","kind":"質問・要望","question":"じゃあ、これ以上どうするのかという問題は別といたしまして、そういう意味では、一人でも多くの方に知っていただくという努力は区のほうとしても、今回の件に限らず進めていっていただきたい。そういう意味では、地域の方が本当に住みやすいまちづくり、安全なまちづくりということで進めていっていただければと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-025"},{"speaker":"須藤委員","kind":"質問","question":"前にも聞いたことがあるんですけれども、品川区がいろいろお手伝いして、まちづくり、再開発をいろいろやってきていただいて、その結果、防災という意味でも安心、また景観的にもきれいなまちになってきていると。その後、その再開発に反対した人が、逆にでき上がってからは非常に協力的になって、そこの自治会の会長になったというような話もちょっと伺ってきたんですけれども。","respondent":"溝口都市開発課長","answer":"ですから丁寧に説明はしてきておりますし、武蔵小山駅周辺につきましては、今回、地区計画を定めている地域につきましては、計画案の段階からも説明会をしておりますし、東京のしゃれた街並みづくり推進条例の手続等もありましたので、通常以上に。","voiceIndex":60,"id":"exchange-026"},{"speaker":"須藤委員","kind":"意見","question":"それから地域のコミュニティがいろいろという話になってくるけれども、先ほど木村委員が言ったように、新しいまちになって、またそこでその人たちがコミュニティをつくっていく、私が住んでいるところも世代がずっと、何世代も地域にいて、その人たちがその時代、時代でまた新しい環境に変えながら、きずななり、まちのコミュニティというのがつくられているという。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"その音頭を取るという意味で、品川区のほうではどのようにお考えなのか聞きたいんですね。その点はどうお考えでしょうか。","respondent":"溝口都市開発課長","answer":"そういったもので周知を図っておりますし、開発計画または別の事業等においても同じように、街並み誘導指針などついてもご説明してきているものです。ですからこれまでと同じように、再開発事業等の中でも説明はしていきたいと考えています。","voiceIndex":63,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"その辺を町会、自治会が、区のかわりではないですけれど、やはりお近くの方が一緒にやっていこうよと、一緒に何かものをつくっていくということは、先ほど木村委員からもありましたけれど、いいまちをつくっていく、愛するまちにしていくということが必要なのではないかと思ったものですから、ちょっとお話しさせていただきました。その辺、もう一度お願いします。","respondent":"片田都市環境事業部長","answer":"先ほどの繰り返しの部分があるかもしれませんけれども、基本的に私どものいろいろなまちづくりのビジョンとか、まちづくりを地域の皆さんと一緒に共有していくことが一番大事だと思いますので、これまでもいろいろな手だてを使って説明してきたところですけれども。","voiceIndex":65,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、各委員から、やはりまちづくりビジョンや街並み誘導指針に対して、地域の方に知ってもらいたいという思いがある中で、やはり知ってもらう努力をすることが必要だし、みんなでまちをつくっていくということが必要なのではないかという意見も、さまざま出されたわけですけれど、そういうことでいえば、開発の具体的なことではなくて、区がつくったまちづくりビジョンと街並み誘導指針について。","respondent":"溝口都市開発課長","answer":"基本的には広報の中でお知らせしているものです。ただ、パルム商店街とかそういったところで改めてというお話であれば、それについては説明をしていきたいと考えております。","voiceIndex":67,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私が聞いたのは、商店街の関係者とか町会長というところには、今までも話してきているわけなので、そうでなくて地域に住んでいる方、住民の方々がぜひ区に説明を求めたいといったときに応えていただきたいと、そういうことで伺ったんですけれど。","respondent":"溝口都市開発課長","answer":"今までも策定経緯の中で、町会、自治会または商店街等についてヒアリング等を行いながらつくらせていただき、その結果としてお話を聞きたいというところがあればご説明をしてきた、そういうふうに考えているものです。","voiceIndex":69,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私がお聞きしているのは、今までやってきた代表の方々ということではなくて、一般の地域の住民の方々から説明会をしてほしいというふうな要望があったとき、応えていただきたいということなんですけれど。","respondent":"溝口都市開発課長","answer":"すみません、一般の方向けにつきましては、広報しながわまたはホームページといったところに掲載しておりますので、そちらをごらんいただきたいというふうに思っております。","voiceIndex":71,"id":"exchange-032"},{"speaker":"須藤委員","kind":"意見","question":"品川区は再開発をいろいろやってこられて、それぞれいろいろな反対があったりして、その都度丁寧に説明して、逆に反対した人が開発が終わってからそこの責任者になるような、きれいなまち、すばらしいまちをつくってきているということもあって、ここで危惧していることもいろいろあろうかと思うんですけれども、最終的には開発を見直してくださいということなので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-033"},{"speaker":"浅野委員","kind":"質問","question":"請願項目について先ほど質問の中でも出させていただきましたけれども、須藤委員と同じになりますけれども、武蔵小山駅周辺再開発の見直しということについては、やはり願意に沿いがたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"事業者の説明の中でも、街並み誘導指針が錦の御旗のような形で、区がこういうふうなことを言っていますのでということで、１４０メートル級のマンションの説明をされているわけですけれども、その大もとになっている街並み誘導指針が、地域の方に説明されるのは当然のことですし、区としても知らせていきたいということで課長が答弁をしながら、地域の住民の方が求めたときには、それには答えられないという。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-035"}]},{"id":"topic-03","title":"平成２４年請願第２０号 区内を循環するコミニティバスの運行を求める請願","agenda":"平成２４年請願第２０号 区内を循環するコミニティバスの運行を求める請願","exchanges":[{"speaker":"須藤委員","kind":"提案","question":"民間の路線バス会社自身が、補助２６号線が全部開通したり何かすれば、また違う考えを持ったりするだろうということで、交通会社ともその辺を意見交換しながら、民間でやってくれる状況になったらまた提案していきたいなと。現状ではなかなか難しいということなので、今日結論を出していただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-036"},{"speaker":"浅野委員","kind":"提案","question":"コミュニティバスについては、公明党からも第３回定例会で提案をさせていただきました。ただ、根底にありますのは、本当にどこまで需要があるのか。今回も具体的な路線が、多分これは一つの例だと思いますが、そういうものも踏まえながら、私はやはりまず最初にこの地域公共交通会議を設置して、検討からスタートする、これをやっていただければと考えています。","respondent":"藤田都市計画課長","answer":"区のほうとしても、今そういう会議体を持ってございませんので、今、例にございました補助２６号線ですとか、補助１６３号線ができ上がった場合、バス事業者に対して、そういう道路が整備されたのでバス路線の検討をというのを個別に行うような形になりますが。","voiceIndex":94,"id":"exchange-037"},{"speaker":"浅野委員","kind":"質問・要望","question":"区からの補助金で例えばコミュニティバスを運行すると、シルバーパスは使えないというのがルールだとも聞いておりますので、そういうことも加味しながら、区民の利便性も図りながら、その会議の中で検討を進めていって、最善の解を求めていっていただければと思います。ここのところは意見ですので、もしお考えがあれば、シルバーパスに関していただければと。","respondent":"藤田都市計画課長","answer":"そういう中で、区のほうとしてもいろいろな場面で、福祉面では、福祉タクシーですとかそういった事業も行ってあります。そういった事業も重ね合わせた上で、地域の公共交通のネットワークがしっかり結べていければいいなと、このように考えているところです。","voiceIndex":96,"id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"この請願に、１時間に数本しかありませんという訴えがあったんですけれど、この実態というのをお聞きしたいなと思いまして、お願いします。","respondent":"藤田都市計画課長","answer":"きょうの請願審査の状況も踏まえた上になるとは思いますが、例えばバス事業者に、そちらのバスについては京浜急行バスになりますけれど、こういった話があります、地域の方からこういう声が上がっています、例えばバスの増便等の検討はできないのか。","voiceIndex":98,"id":"exchange-039"},{"speaker":"吉田委員","kind":"意見","question":"今、おっしゃっていただいたので、それはやはり一番先に、道路の見直しとかいろいろありますけれど、最初に京浜急行バスのほうにお話をしていただくような形で、第一歩を進んでいけるのではないかと私も思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":100,"id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして質問ですけれど、１つは東京都のコミュニティバスに対しての補助金というのがどうなっているのかということをお聞きしたいのと、それからここにあるように、今２３区のうち１９区で既に運行されていますということですが、前回の平成２３年２月の請願審査のときから、２３区の中で増えているところがあったら、そこの実態も教えていただきたいと思います。","respondent":"藤田都市計画課長","answer":"当時と今で、私が説明している数は変わっていません。１９の区が導入をしているという形になってあります。それ以外の区というのは、品川区と港区と豊島区、千代田区です。千代田区は乗合タクシーというような形で運行しています。","voiceIndex":101,"id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域ではさくら会の老人保健施設に行くのにすごく大変で、家族の方が入っているときにタクシーで、近所の人と待ち合わせして一緒に行ったりとかしているというふうな声も聞いたんですけれど、例えばしながわ水族館のバスを、大井町からさくら会のところを通ってしながわ水族館に行くような、そういうようなことからでも開始できないかという要望もいただいたんですけれど、そこら辺はいかがでしょうか。","respondent":"藤田都市計画課長","answer":"今回の一般質問の中のご答弁でも申し上げましたとおり、補助１６３号線ですとか補助２６号線など、将来の道路ネットワークの整備も見据えることとあわせて、高齢者人口の増加など社会的要因も考慮して。","voiceIndex":103,"id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"先ほど課長からもありましたように、２３区の中で結局２１区がそういう形で、乗合タクシーを含めてコミュニティバスをされているということでは、私は他区で仕事をしている方から、他区はコミュニティバスがすごく便利で、こういうものが品川区にもあったらいいのにということをいつも伺っているんですけれども、そういう点では区民の方も、いろいろなところへ行ったときにコミュニティバスがあって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-043"},{"speaker":"浅野委員","kind":"質問","question":"質問の中でも教えていただきましたけれども、地域公共交通会議を設置して、その中で十分もんでいただいて、それで必要に応じて設置をするということで、具体的な路線については、この場で採択というわけにはいかないと思います。シルバーパスについてもその中で検討になると思いますので、今回は願意に沿いがたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":116,"id":"exchange-044"}]},{"id":"topic-04","title":"を行います。 初めに、(1)専決処分の報告","agenda":"を行います。 初めに、(1)専決処分の報告","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"３年前の２月１５日に天井板が落下する事故が起きたというのは、何でこんなことがあったんでしょうか。","respondent":"大串住宅担当課長","answer":"こちらの２月１５日に発生した件ですが、この方が住んでいる上階の部屋の漏水によるものです。その漏水で水がたまって、最終的に天井が、この方の部屋の和室になりますけれども、和室の天井が落ちた、はがれたです。","voiceIndex":126,"id":"exchange-045"}]},{"id":"topic-05","title":"品川駅南地域 まちづくりビジョン 中間まとめ","agenda":"品川駅南地域 まちづくりビジョン 中間まとめ","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そしてこれは、本当にこのまちそのものが大きく変わっていくというビジョンになると思うんですけれども、今回は中間のまとめということで、平成２４年度末には取りまとめをしていくということなんですけれど、中間まとめから取りまとめまでは、どのようにこれを地域の方に知らせて意見を求めていくのかということについてもお聞かせください。","respondent":"溝口都市開発課長","answer":"今後、中間まとめについてどのように地域の方にということですが、先ほど来説明がありましたように、当地区につきましては推進協議会が立ち上がっています。","voiceIndex":137,"id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここに住む方にとっては、大きな影響を受けるまちづくり構想になってくると思うんですけれど、午前中にあった武蔵小山のまちづくりビジョンとか街並み誘導指針などについては、広報でもお知らせをし、またホームページにも出して、住民への説明会というところにはいきませんでしたけれど、区民へのお知らせというのはどういうふうにするのかということと。","respondent":"溝口都市開発課長","answer":"ただ、先ほどの推進協議会には、地元を代表される方々がご参加になって今回のまちづくりビジョンをまとめている兼ね合いがありますので、そちらの方たちと十分お話をしながら、取りまとめに向けて進めていきたいと考えているものです。","voiceIndex":139,"id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この推進協議会のメンバーはどういう方で、何人ぐらいいらっしゃるのかということを教えていただきたいのと、推進協議会というのはまち全体から選ばれた人ということなのか、そこら辺のところも含めて教えていただきたいと思います。","respondent":"溝口都市開発課長","answer":"その中には地元の町会長、自治会長、商店街長も入られておりますので、そういったところでしっかりと説明をし、ご意見を聞きながら取りまとめをつくってきたというふうに考えているものです。","voiceIndex":141,"id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"同じようなパターンになっていくのではないかと思うんですね。そういう点では、この９２ヘクタールすべての町会から自治会長が入られているのかどうかわからないですけれども、そこから地域の皆さんのところに、この計画が周知されるということになるのかどうか、あと企業も入っているということですけれど、どんな企業が入っているのかも教えていただきたいと思います。","respondent":"溝口都市開発課長","answer":"冒頭の説明にもありましたように、まず地域の声を代表して品川区のほうへ、当地区も含めてまちづくりをどうするのかというのが、町会長連盟から要望書が出されています。その流れを受けて推進協議会をつくり、推進協議会の中でもまちづくり構想をまとめて、品川区に提案されたと。","voiceIndex":143,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、これも多分コンサルタントが入ってつくられていると思うんですけれど、そのコンサルタントはどこなのかということも教えていただきたいと思います。","respondent":"溝口都市開発課長","answer":"当然、都営住宅につきましては東京都が管理しているものですので、東京都が今後どういう形で都営住宅を考えるか、そういったものを十分聞きながら、まちづくりをすすめていかれるというふうに考えているものです。","voiceIndex":145,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都営住宅は今でも足りなくて、募集するたびに高い倍率で、かなり切実に求められているところですので、絶対にここをなくすというふうなことはしないまちづくりをしていただきたいと思います。それと、１万３,９２０人、多くの方がかかわっている地域での、大きなまちの構想ということになりますので、改めて私は全地域の方々を対象にした説明会をぜひ開いていただくように、強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-051"},{"speaker":"沢田委員","kind":"意見","question":"品川駅南地域というのは、本当に品川区の中でも一番古いまちなのと、歴史と伝統ときれいな水辺と、とても整備された旧東海道があるところだと思うんですけれども、そういった中でまちづくりが進んでいくということは本当に楽しみなことなんですが、その中で、最初のところにも挙げられたリニア中央新幹線の品川駅南口への誘致ということで、このまちに関しては以前からそういった話があるみたいですけれども。","respondent":"溝口都市開発課長","answer":"今後、適時、適切な形でこのビジョンに書かれている南口の実現に向けて、さまざまな形での要望と活動等を行っていきたいと考えているものです。","voiceIndex":148,"id":"exchange-052"},{"speaker":"沢田委員","kind":"質問","question":"港区のほうでは水陸両用車を、この間テレビでもやっていましたが、ああいった試みとか、いろいろやられているかと思うんですけれども、こういうところを利用して、今後品川区でもそういった水陸両用車だとか、もっと定期船を運航させるとか、あわせてこの水辺の近隣の整備ということを考えられているかと思うんですが、その辺もこういうところに含まれているということでよろしいでしょうか。","respondent":"溝口都市開発課長","answer":"水辺の利活用につきましては、水陸両用車まではちょっと想定していないんですが、当然品川駅と近接する水路を使って、羽田空港に不定期利用できるような桟橋が設置されている状況がありますので、そういったところで。","voiceIndex":150,"id":"exchange-053"},{"speaker":"沢田委員","kind":"質問・要望","question":"近隣の区もいろいろ、港区も江東区も水辺がある、運河がある区とも協力を進めながら、こうやって水辺の開発というのはさらに進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-054"},{"speaker":"浅野委員","kind":"提案","question":"今年の５月に、推進協議会から区にまちづくり構想が提案されて、今回の中間まとめになったということですが、この推進協議会の意向というのは、どの程度というんでしょうか、ここに含まれているのか、それとも何か協議会から提案されたことで大きく変わった点とか、そういうもの、大きいもので結構ですので、教えていただければと思います。","respondent":"溝口都市開発課長","answer":"ですから、ここに書かれている拠点の考え方ですとか軸、または土地利用、ゾーニングの考え方、そういったものを踏襲しながら、今回中間まとめとしてビジョンをまとめているものです。","voiceIndex":153,"id":"exchange-055"},{"speaker":"浅野委員","kind":"質問","question":"確かに近場には旧東海道ですとか見るところはあるかと思うんですけれども、どうももうちょっと、いい意味での華やかさみたいな、そういうものについては、全体的にどんなものだろうと考えられているのかなと。個別にあれば教えていただければと思います。","respondent":"溝口都市開発課長","answer":"そういった中で、まちづくりを進めていく中で当然来てもらえるような、また来ていただいて楽しんでもらえるような、賑わいの持てるようなまちづくりを進めたいと考えておりますし、そういった中で、ここでいきますと軸の形成として、歴史と賑わいの都市軸の形成ですとか。","voiceIndex":155,"id":"exchange-056"},{"speaker":"浅野委員","kind":"質問","question":"神社・仏閣などを中心に回るということなので、それなりに満足はしていただけるかなと思うんですけれど。やはり旧東海道というと、皆さんご存じのとおりでありますので、一度は来てみていただければと思うんですけれども、それにふさわしいというんでしょうか、応えられるような形を、ぜひとも考えていただければと思います。","respondent":"溝口都市開発課長","answer":"そういったものにつきましては当然、同じ方向を見て、同じようにいろいろなまちづくりを進めていく中で、ただ単に新しいものをつくるだけでなく、その地域の伝統と文化、そういったものが感じられるようなまちづくりを進めていきたいと考えているものです。","voiceIndex":157,"id":"exchange-057"}]},{"id":"topic-06","title":"第二次品川区環境計画（素案）","agenda":"第二次品川区環境計画（素案）","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"３ページになるんですけれども、計画の位置づけの中で右の下に品川区環境計画があって、その中で地球温暖化対策地域推進計画、地球温暖化防止対策実行計画が記載されておりまして、この実行計画のほうの中に、第三次ですけれど平成２５年度から２９年度ということが含まれていますので、この第三次につきましては当然環境計画の全体をにらみながら。","respondent":"野呂瀬環境課長","answer":"この実行計画につきましては今、実際に、来年の３月に環境計画を策定するのとあわせて、当然策定しているということで、今ちょっとまだ詳細は申し上げられないんですけれども、大体数字でどういうふうな形にするとかいうのはなかなか難しいのではないかということで、じゃあ。","voiceIndex":166,"id":"exchange-058"},{"speaker":"浅野委員","kind":"確認","question":"私が記憶しているところによりますと、品川区としては、４つの温室効果ガスがあるけれども、実質的にはもうＣＯ２に絞って削減をしているというふうに伺っていたんですが、その真ん中の表のところにありますのが、「品川区内の温室効果ガス排出量の変化」ということになっておりまして、これはどうせだったらＣＯ２と、二酸化炭素にすべきではないかと私は思います。","respondent":"野呂瀬環境課長","answer":"これは一般質問も含めて答弁しているとおりです。それと申しわけございません、最初に委員がおっしゃった９ページですけれども、この温室効果ガスはおっしゃるとおりです。二酸化炭素の排出量です。これはですから、二酸化炭素の排出量。","voiceIndex":168,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１２月１２日からパブリックコメントが始まるんですけれど、このパブリックコメントをとるに当たっての区民への周知というのは、どういう形にするのかを教えてください。","respondent":"野呂瀬環境課長","answer":"広報しながわの１２月１１日号に掲載いたします。はホームページ等で、周知徹底を図ってまいります。閲覧場所につきましては、環境課の窓口、区政資料コーナー、図書館、各地域センター、環境情報活動センター等です。","voiceIndex":170,"id":"exchange-060"}]},{"id":"topic-07","title":"品川区一般廃棄物処理基本計画（第３次・素案）","agenda":"品川区一般廃棄物処理基本計画（第３次・素案）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"基本的なところで教えていただきたいんですけれど、１５ページの資源のリサイクルフローというところで、真ん中ぐらいの汚れていないプラスチック製容器包装というものの資源化はかなり進んできたのかなという思いがしているんですけれど、実際はどのような形になっているかというと、民間施設で選別・圧縮梱包されて、再生処理工場でガス化・パレット・アンモニア還元剤という形になっているんですけれど。","respondent":"太田品川区清掃事務所長","answer":"すみません、何度も見たつもりですけれども、ご指摘の部分は統一します。それから１５ページの汚れていないプラスチック製容器包装についてですけれども、これはご案内のとおり本格実施が平成２０年１０月から、分別変更に合わせて実施させていただいたところです。","voiceIndex":177,"id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはりこれからもごみ減量というのは本当に求められていくと思うんですけれど、資源化のところが達成していないということで、この概要版の３ページのところにきれいにカラーで、燃やすごみの組成割合ということで、紙類とかプラスチックとか、そういうものもまだまだ含まれているというところでは、ここのところを資源化のほうに持っていくことができるのかなと思うんですけれど。","respondent":"太田品川区清掃事務所長","answer":"毎年、年末にごみ・リサイクルカレンダーを配っているというのも実施してきてありますけれども、それだけではなくて、今後はやはり区としても地域の中に入っていって、個別といいますかある程度の人数、できれば１０人から２０人ぐらいの単位で。","voiceIndex":179,"id":"exchange-062"}]},{"id":"topic-08","title":"河川活用交流事業支援（目黒川乗船見学会）","agenda":"河川活用交流事業支援（目黒川乗船見学会）","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"このような見学会ということで、子どもたちも非常に楽しみにしていると思いますが、やはりこういう変わったところに行くと、子どもたちもどうしてもいろいろと動きたいとか、見たいとか、そういうことになるかと思うので、事故が起きないような安全対策というのはきっちりされていると思うんですけれども、その点についてちょっと内容をお聞かせいただきたいと思います。","respondent":"武藤河川下水道課長","answer":"あわせて実施機関でありますしながわ観光協会には、実施当日に、例えば万が一大雨が降ったときの対応だとか、そういったことにつきましても、現在確認を行っているところです。そういった安全対策をとりながら、乗船する皆様にはしっかり楽しんでいただければと考えています。","voiceIndex":199,"id":"exchange-063"},{"speaker":"須藤委員","kind":"質問","question":"これを見るのはどのぐらいの時間に行くのでしょうか。それと同時に、河川活用交流事業支援ということでやろうとしているのに、もう少し陽気のいいときにやればいいのに、寒い時期に、さっきイルミネーションを見ると聞いて、そこまでやるのかと思ったんですけれど、どういうふうに見るつもりですか。雨水調節池とかそういうのは、夜だとあまり見えないでしょう。その辺のあれは、何でやるんですか。","respondent":"武藤河川下水道課長","answer":"こういった事業は今回初めてなので、実施状況を見ながら、また今後検討していきたいと思っています。時間帯につきましては、実は船の出航が大体３時半ごろを予定しておりまして、日が落ちるには少し早い、まだ明るい時間帯ですので、施設等を見学できる状況です。","voiceIndex":202,"id":"exchange-064"},{"speaker":"須藤委員","kind":"意見","question":"観光協会と連携するので非常にいいし、もしできたら、一番人気があるのは桜の時期、季候もよくなるし、あそこは普通でも桜を見に乗っていくぐらいに船が出ていくので、そんな時期的なものを上手にまた活用して、ぜひ子どもたちが水辺に親しむようなあれを、こういった支援金というものを、できるだけ時期も選んで使ってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":204,"id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この河川活用交流事業支援金の中身をちょっと教えていただきたいんですけれど、国からの支援金ということだと思うんですけれど、子ども２０名の６日間で１２０名で、どれぐらいの予算なのか、これから毎年これを続けて活用ができるのかというあたりも含めて、教えてください。","respondent":"武藤河川下水道課長","answer":"来年度以降ですけれど、またそれは今後、こういった実施状況を見ながら考えていきたいと考えています。今回、本事業に対しましては、必要最小限の、実施する部分の直接経費につきまして、約５０万円を支援している形になっております。","voiceIndex":205,"id":"exchange-066"}]},{"id":"topic-09","title":"耐震改修促進計画の改定における耐震化率","agenda":"耐震改修促進計画の改定における耐震化率","exchanges":[{"speaker":"木村委員","kind":"質問","question":"１枚目の資料ですけれども、この表の中で、区有建築物で防災上重要な施設、これが９１.８％、その他の施設というのが７９％になっていますけれども、この防災上重要な施設のマイナス８.２ポイントはどういう施設とか、どういう建物でしょうか。それと、その他の施設はマイナス２１ポイントになっていますけれども、どんな施設がありますか。教えてください。","respondent":"品川防災整備担当課長","answer":"ちょっと詳しいことはわかりませんが、学校等、保育園、地域センター等で少し終わっていないところがあるというような報告は聞いております。それからその他の施設ですが、高齢者福祉施設とか公園管理施設等が、こちらのその他の施設に入ります。","voiceIndex":212,"id":"exchange-067"},{"speaker":"木村委員","kind":"意見","question":"そういうことでマイナスポイントがありますけれども、これは早急に、先ほど耐震化目標９５％と言われましたけれど、どちらにしてもこれはすべての目標だと思いますけれども、特に今言われたようにその他の施設で２１％マイナスということですが、そういうところにもやはり高齢者施設とか、大事な部分もたくさん入っていると思いますので。","respondent":"品川防災整備担当課長","answer":"こういった公共の施設というのは災害時の避難所等にもなりますので、非常に重要な施設ですので、早急に耐震化率を上げていくように努力いたします。","voiceIndex":214,"id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"重点施策のところで木造住宅、非木造住宅と耐震化の支援があるんですけれど、その中でも、木造住宅の耐震化というのは本当に緊急に進めていくことが大事だと思うんですけれど、この支援策を、新たな計画に向けて充実をさせるというところでの区の考え方というのはいかがでしょうか。","respondent":"品川防災整備担当課長","answer":"やはり品川区の課題としましては、木造住宅密集地域を多く抱えております。こういった観点からしますと、やはり耐震をしていただく、かつ不燃化対策も同じような効果が出るような手法で、助成をしていく部分を充実させていきたいと考えております。","voiceIndex":216,"id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"耐震診断をして、その後の補強工事につなげていくというところで、訪問がまた始まったと思うんですけれど、そういうところも含めて、これから一番困難になっていくのは財政的に大変だというところがありますので、耐震診断の状況から補強工事の助成、不燃化も合わせてですけれど、そういうところでの助成の充実もぜひ、プラスでやっていただきますように要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-070"},{"speaker":"浅野委員","kind":"質問","question":"この耐震化率をどうやって上げるかということで、私どもも区民の皆さんからいただいたさまざまな意見を、この建設委員会でも何度も出していますけれど、例えば小規模マンションというものを対象に加えてはということで、裾野を広げていくという考え方でどうなのかということですとか、あとは建築基準法に適合していないといったらいろいろあるかもしれませんけれども、そういうところの救済措置みたいなこと。","respondent":"品川防災整備担当課長","answer":"そういうところで、やはりここの部分に手を出さないといけないのではないかというような考えもあります。現時点では、新宿区等で違反建築物についても耐震助成をしていくというような動きもあります。こういった状況も踏まえて、今後検討していきたいと考えております。","voiceIndex":219,"id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで、旧耐震だけに限らず、耐震診断を受けて、補強工事をしたいという方に対しては、助成制度をぜひつくっていただきたいと。ぜひそういうところにも支援を増やしていただきたいと思うんですけれど、いかがでしょうか。","respondent":"品川防災整備担当課長","answer":"ということで、昭和５６年６月以降に建った家に対して、助成をしてくださいという声はよく聞くのですが、基本的に建築確認をしている段階で耐震性がある物件に対して、助成を行っていくというのは、非常に難しいというのが現状です。","voiceIndex":222,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"確認をとっているにもかかわらず、それで足りたので、本人は大丈夫なのではないかと思っていたら、実際にやってみたらその基準を満たしていなかったということなので、それは確認をおろしたところの問題になるのか、どうなのかわからないですけれども、でも実際はそういう家屋がデータとして、昭和５６年６月以降に建てた建物は必ず大丈夫だという状況ではないというのはデータとしてもあると思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも数十年前のことだから。実際やはり困っているということなので、ぜひご検討いただいて、受けられるようにしていただきたいと思いますけれど、だめですかね。","respondent":"片田都市環境事業部長","answer":"建築確認の話もありましたので、私のほうからお答えしますと、昭和５６年６月以前のものについては、計算のやり方が実は変わりましたので、それ以前の建物、特に阪神・淡路大震災の段階で、昭和５６年以降の建物であれば大きな被害は出ていなかったと。","voiceIndex":225,"id":"exchange-074"},{"speaker":"木村委員","kind":"質問","question":"概要版のほうで耐震化の目標が書かれていますね。これは１００％を目指すのが当たり前だと思うんですけれども、９０％以上というのはどうしてでしょうか。","respondent":"品川防災整備担当課長、片田都市環境事業部長","answer":"この法の中では、国、都にのっとって市町村は目標を定めるというようなことが書いてあります。今回、東京都のほうが９５％という形で出ておりますので、それに連動した形で目標を挙げております。そういう中で新たに耐震改修促進法の改正を行って、たしか平成１８年あたりには、国のほうの方針として一応９０％を目指すと。","voiceIndex":227,"id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4060#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":73721,"voices":238}},{"id":"h24-20121127-9","meetingId":"h24-cm11","date":"2012年11月27日","dateIso":"2012-11-27","committee":"文教委員会","time":"午前１０時００分～午後３時１４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の(1)平成２５年度入学希望申請の状況","agenda":"の(1)平成２５年度入学希望申請の状況","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、待機が随分紹介されましたけれども、これだけの学校数、小学校、中学校合わせて増えているということは、今までの数字からすると、どういうふうに見たらいいのか、それを教えていただきたい。とりあえずそれをお願いしたいと思います。","respondent":"和氣学務課長","answer":"昨年よりは待機は増えているという結果になっております。","voiceIndex":9,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"増えているということはわかりましたけれども、どういう傾向にあって、どういうふうに教育委員会としては見ているかということについて教えていただきたいと思います。","respondent":"和氣学務課長","answer":"抽選校が増えているのは、小学校１校、中学校１校ですので、さほど多く増えたという部分ではございません。冒頭で説明したとおりです。","voiceIndex":11,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"前から私たちはずっと言ってきたんですけれども、公立で抽選をするということをずっと疑問に思っているところがあって、品川区は、当然、学校改革を進められて、選ばれる学校を目指してきた。だから、ハードはすぐつくれないことはわかっているけれども、次のステップを考えたらどうですか。これだけ抽選で待たされているわけだから、こういうふうにいつもなるんですが、改めてお考えをお聞かせください。","respondent":"和氣学務課長","answer":"基本的に私どもは、今、どの学校も非常によくなっているので、なるべく地元の学校を選んでいただきたいということでお願いをしたり、学校でも積極的にそういう指導をしていただいて、子どもに来ていただくように頑張ってくださいねということでお願いをしていますが。","voiceIndex":13,"id":"exchange-003"},{"speaker":"伊藤委員","kind":"質問","question":"品川区の教育改革がすばらしい、だから○○中学校、○○小学校を選びました、ところがそれで抽選になってしまうということはどうなのかなというのは、それは素直な思いがあるわけであって、そうすると、さらにこの教育改革をこれからも進めていくわけでしょうから、私たちとしては抽選がない、希望する子どもたちが、もともと公立で抽選はあり得ないんですから。","respondent":"和氣学務課長","answer":"繰り返しになってしまいますが、ハード面も含めた検討をしているところでございまして、今もしていますけれども、しっかり子どもたちが希望の学校に入れるように、いろいろ考えて、知恵を出してまいりたいと考えています。","voiceIndex":15,"id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ここで話してもなかなか出てこないことはわかっているのであれなんですけれども、でも、繰り返すようだけれども、品川区は小学校、中学校を変えたい、教育内容を変えたいということでやってきた、結果として保護者の方々はそれに対して一定の評価をしていただいて、私立よりも区立の小・中学校を選んだわけですから、それはしっかり受けとめてあげて、さまざまなハードの制約があることはわかるんだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"これは６歳児の人口ですから、今後少なくとも６年間、どのくらい、まだ品川区の人口は増えていくと思うんですけれども、それを特にどういうふうに吸収しようと考えていらっしゃるのか、特に私は地元が御殿山小学校のエリアなんですけれども、これは、入りたいといったときに、ほかの学校も希望してくれるか、私立小学校に行ってくれないかと、学区の学校に入り切れないですよね。","respondent":"和氣学務課長","answer":"そういう意味で、そこも含めまして、私どもとしてはどう子どもたちをしっかり就学させるかという抜本的な見直しをしなければならないと考え方を固めつつあるところで、今後十分検討して、早いうちに方針を示していくというふうに思っております。","voiceIndex":18,"id":"exchange-006"},{"speaker":"阿部委員","kind":"質問","question":"抜本的な対策という、例えばどういうことを考えていらっしゃるのか、今の段階で言えることだけで構いませんので、見通しとともに教えていただければと思います。これは来年度以降の保護者の選択にも大きくかかわってくる部分ですので、ぜひお考えを聞ければと。","respondent":"和氣学務課長","answer":"これはまだ内部で、私どもの課の中で検討しているものですので、それを含めまして、基本的には全体で検討していただくというような形で思っておりますが、まだ課内での内部検討ですので、その内容については控えさせていただきたいと思います。","voiceIndex":20,"id":"exchange-007"},{"speaker":"阿部委員","kind":"質問・要望","question":"ありがとうございましたというか、控えるような話なのかなと思うんですが、これは、つまり教育委員会の中だけで話していることなんでしょうか。私はこれはまちづくりにかかわることだと思いますので、むしろ、教育委員会だけでない検討をしていただきたいと思うんですけれども、その辺はいかがでしょうか。","respondent":"和氣学務課長","answer":"もちろんシミュレーションをやっていますので、その対策は別にして、どのぐらい増えていくかをシミュレーションし、区長部局にもその情報提供をしていまして、こんなふうな状況になってありますということで、対策が求められますというような話はしています。","voiceIndex":22,"id":"exchange-008"}]},{"id":"topic-02","title":"の(3)区立八ツ山保育園の耐震化工事ついて","agenda":"の(3)区立八ツ山保育園の耐震化工事ついて","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"保育園の耐震化については、八ツ山保育園、保育園全体の耐震化の関係で見ると、ほかはほとんど済んでいると思っているので、最後のほうの部分なのかと思っているんですけれども、そのあたりを確認したいので教えていただきたいのと、東京都の都営住宅と一緒なので、東京都が進めるのに合わせて八ツ山保育園の耐震化も進めると話は聞いていたので。","respondent":"立川保育課長","answer":"移転先ですが、現在のところ、旧品川・大崎土木事務所の跡地、現在、仮設で大崎在宅サービスセンターが入っておりますが、平成２６年１月以降に移ることから、現在、その場所を候補地の一つとしております。","voiceIndex":31,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"移転期間は２年間だけれども、今までの例でいうと、１年ぐらいだという話なんですけれども、そうすると、この２年間の間、１年ぐらいに縮小することもあり得ると理解していいのかどうか、そこと、あともう一つは、移転先が品川・大崎土木事務所というと、どこでしたか。そこら辺、旧品川・大崎土木事務所だけだと位置的によくわからないので、どこかを教えてください。","respondent":"立川保育課長","answer":"工事期間につきましては、先ほど説明したとおり、東京都で本年と来年に実施設計をするということになりますので、その結果が出てみないと、いわゆる工事期間が確定しないということで、先ほどの発言を訂正しますけれども、現在のところ、２年を予定しています。","voiceIndex":33,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"わかりました。全工事移転期間というのは最大限２年というところ、具体的にはなってから、さらにあれですけれども、この関係で、できるだけ近いところが利用されている保護者の皆さんにとっては必要かと思ったので、位置の確認をしたいと思いました。東京都が実施することではあっても、この期間、事故もなく、しっかりやっていただきたいということを改めて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"幾つかお伺いしたいと思います。これは経費の負担の考え方なんですけれども、この工事にかかるものというのは、保育施設も含めて、すべて都にやってもらえるものなのか、それともある程度、案分なのか、それから引っ越しにかかわる経費とか、仮設にかかる経費とか、その辺はどのようにやっていかれるんですか。","respondent":"立川保育課長","answer":"耐震改修にかかわる経費につきましては、全額東京都持ちです。仮設への引っ越し、また仮設の費用につきましては、現在のところ、区費ということになっております。","voiceIndex":36,"id":"exchange-012"},{"speaker":"阿部委員","kind":"意見","question":"耐震は保育園部分、でき上がった後の内装なんかは変わることになるのかしら。耐震で何かくっつけるだけで、中身は全く変わらない状態でまたオープンみたいな感じか、その辺のイメージを。","respondent":"立川保育課長","answer":"耐震改修工事にかかわる部分につきましては、東京都が実施なので、改修後、そのまま使えるのであれば、そのままというふうに現在のところは考えております。","voiceIndex":38,"id":"exchange-013"},{"speaker":"阿部委員","kind":"質問・要望","question":"耐震改修ということなので、耐震強度が上がればそれで終わりなのでしょうけれども、私も八ツ山保育園の中がどうだったか、幾つか質問したいのですが、ただ、それなりに十分古いものだったと思うので、この機会に子どもたちの環境をよりよいものにしていくという発想で、ぜひこの工事についても考えていただきたいと思います。ご答弁あればお願いします。それが１点です。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"は１点目の、内装等の改修も含めた対応について、これにつきましては、継続いたしまして対応したいと考えております。２点目のご質問の仮設の大崎在宅サービスセンターですけれども、これは先ほども課長が申し上げたとおり、今の段階では候補地の一つとして考えておりますので、具体的にここが決まれば。","voiceIndex":40,"id":"exchange-014"},{"speaker":"阿部委員","kind":"質問・要望","question":"まだ未定の部分が多いということで、幾つか選択肢がまだあるのかなと思います。３点目、簡単な話ですが、これの工事については都主体で行われると思うんですけれども、その工事や移転にかかわる保育園利用者、それから今後の利用、潜在的な利用希望者に対するお知らせというのは、ぜひ早い段階でやっていただきたいと思います。これは、この時期ですので、また要望しておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"必要な費用をかけて、父母の皆さんにだって、子どもにだって不便をかけるわけですから、でき上がったときにはきれいな園で、豪華にするという必要はないと思いますけれども、必要な改修、改装というのは行うべきだと思うんですけれども、何かそのような考えがないみたいな感じで聞こえたので、そうでなければいいんですけれども、そのあたりを確認したいと思います。","respondent":"立川保育課長","answer":"八ツ山保育園につきましては、これまで大規模改修は実施しておりません。それから、補強に伴って改修を進めるべきではないかというご意見ですけれども、その辺につきましては、今後、現在は未定ですので、今後は施設の状況等を勘案いたしまして、考えていきたいと考えています。","voiceIndex":44,"id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"大規模改修というのは何年に１回ぐらいのペースでしたかしら。そこを確認したいのと、大規模改修をしてこなかった理由というのは何だったのか、そのあたりを、４１年もたっているから、していて当然だと私は思っているんですけれども、何か特別な理由があったのかなと思ったんですけれども、伺います。","respondent":"立川保育課長","answer":"八ツ山保育園に関しましては、工事履歴等の詳細というのは、今現在、手元にございませんので、詳しい話はできないところですけれども、大規模改修につきましては、各施設の状況を見まして、計画的に現在進めているところですので、八ツ山保育園については。","voiceIndex":46,"id":"exchange-017"},{"speaker":"南委員","kind":"質問・要望","question":"だから、老朽化していないという、チェックをして、そういうふうな判断をして、大規模改修にのってこなかったのかなと思っているんですけれども、そういう地域的なことも含めたチェックの上で、する必要が今のところはなかった、先送りにしても大丈夫だったというふうに、そういう判断をしたことなのかというのを確認したいのと、あと。","respondent":"立川保育課長、金子子ども未来事業部長","answer":"大規模改修につきましては、何年に１回というようなルールというものはございませんが、例えばですけれども、東大井保育園につきますと、西暦でお話ししますと、１９６８年に開設しまして、１９８４年に改修をかけたとか。今、先ほど課長が申し上げたとおり、手持ちでその部分の状況が、八ツ山保育園としてはどの部分を改修して、どの部分を改修していないか、今、わかりませんけれども。","voiceIndex":48,"id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、そうであったにしても、やはり４１年間、同じ壁紙だったりとか、そういう室内の状況というのは相当、４１年もたっていれば劣化もしますし、白い色も薄黒くなってくるし、そういう点では、これを機会にきちんと明るい保育園にリニューアルできるようにするべきだと思うし、担当のところでも、当然、そういうふうなお考えは持っておられると思いますので、改めてそこはぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-019"}]},{"id":"topic-03","title":"の私立保育園の移転","agenda":"の私立保育園の移転","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"３歳になったら新しい保育園に行かなければいけないという保護者と子どもさんの立場から見ると、５歳までずっと続いて行けるという点では非常にいいことなのではないかと考えていますので、評価をしたいと思って、見守っていきたいと思っていますけれども、先ほどのところについてはどういうふうになっているのかをお伺いしたいと思います。","respondent":"立川保育課長","answer":"大崎三丁目ですが、この辺はほぼ固まっている状況でございまして、東京都との協議等におきまして、まだ正式に終わっていないということで、予定ということで書かせていただいております。","voiceIndex":56,"id":"exchange-020"},{"speaker":"南委員","kind":"確認","question":"そうすると、１年数カ月の間に建物を建てて引っ越しをしなくてはいけないわけですから、そして、今、駐車場だから、更地にしてつくるという点では、東京都との協議がまだ全部終わっていないから、こういう発表なんだというところはわかったんだけれども、建設するわけですから、当然、可能な、そういう１年３カ月、４カ月のことで、１カ月前ぐらいに準備で建物が建ち上がらなくてはいけないわけですよね。","respondent":"立川保育課長","answer":"いわゆる新規、移転、開設ということで、ほとんど細かいところまで詰めている状況ということで伺っておりますので、あと１年４カ月ほどありますので、再来年４月の開設には間に合うとお伺いしております。","voiceIndex":58,"id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問","question":"当然、移転、それから、あと事業拡大とかもあるでしょう。そのときに、行政が一定関与して、その当該の企業の情報をつかんで、把握して対処しているのかということが気になりましたので、この移転についても、行政はどういうふうにかかわって、その情報をつかんで、それで、要するに区民の方々に対する情報提供も指導するところがあると思うんですけれども、そのお考えはどうでしょうか。お聞かせください。","respondent":"立川保育課長","answer":"いわゆる移転の決定までに区としてどういうふうにかかわっていくか、関与していくかですが、移転の相談の段階から、こちらとしてはお話を十分お伺いして、移転先等についても、できれば。","voiceIndex":60,"id":"exchange-022"},{"speaker":"伊藤委員","kind":"確認","question":"だから、行政が許可を出す保育園なわけです。それに対して、品川区の行政として、当該企業とどういうふうに対策を取りながら、おっしゃるとおりそれはおそらく待機児童対策のそういうところに移転してもらって解消を図る。だから、そういういろいろな、マネジメントというか、そういうことについて業者のほうとどのようにかかわっていますかということを確認したいんです。いかがですか。","respondent":"金子子ども未来事業部長","answer":"ただ、この時期に報告しなければならないのは、今、保育園の申し込みの時期に当たっておりまして、在園の方々、それから新しい申込者の方々に説明をしなければならないということがありましたので、それに先だって委員会にご報告申し上げているです。","voiceIndex":62,"id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問・要望","question":"要望です。つまり部長が最後におっしゃったところが欲しかったわけです。認可保育園ですから、行政がしっかり保育園を認可することに対しては品川区が責任を取るのは当然であって、その責任範囲の中で、こういう私立保育園がさまざまな事業を獲得するに当たっては、ぜひしっかり関与していただきたいということを願っておりますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-024"},{"speaker":"阿部委員","kind":"質問・要望","question":"７０名定員ということはそれなりに広いものなんだろうと思うんですけれども、どんな感じの建物になるのか、予定で言えるところがあれば、例えば平屋なのか、２階建てなのか、計画や平面図などがあれば、そういったもの、もし今の形で言えるものがあれば教えていただきたい。","respondent":"立川保育課長","answer":"大崎三丁目に移転するということにつきましては、１２月より、このエリアですから、委員おっしゃるとおり位置的には、自転車等でも距離があるところなので、保護者の方から具体的にどの辺ですかというふうなお話がありますので、大崎三丁目に移転する予定である旨。","voiceIndex":65,"id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"来年度の募集については、当然、今の保育園のところで募集するわけですよね。だから、平成２６年度オープンですから、そのときは大崎三丁目で紹介をするということになるんですよね。どんなふうに区としては指導していただいているのか。","respondent":"立川保育課長","answer":"現在、２歳児までの園ということで、実際、この移転により、影響を受ける子ども、現在の０歳児で入園しているお子さんに対しまして、１歳児と２歳児につきましては、３歳以降、ないですので、当然、転園等を想定された形で対応するのは０歳児。","voiceIndex":67,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、０歳の子どもさんですから、今、何人だろう。そして引っ越し直前のこの時期になったときに、やはりあっちに自分も行くというのは、通園・通勤も含めて、できないわという保護者がいた場合には、区の対応というのはどういうふうになるんですか。","respondent":"立川保育課長","answer":"これは移転ということなので、それぞれ個別に保護者の方に説明するかどうかということにつきましては考えてはおりません。","voiceIndex":69,"id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"そこについてはこれからの検討となるんでしょうか。具体的に心配されることが出てくると思うので、今からそれなりの対策をとっておく必要がある、対策というか、準備をしておく必要があるのではないかと思いますので、ぜひそこも含めて、困ったよということがないようにしていただきたいと思います。今回、このときでは要望にとどめておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-028"},{"speaker":"阿部委員","kind":"質問","question":"先ほど出ました私立保育園、認可保育園の移転に際して、これは大崎三丁目の土地を取得すると結構コスト的にもかかると思うんですが、一方で助成等々も出やすかったかなと思うので、お金をどのような形で、今年は大丈夫とか、その辺の仕組みだけ教えていただけますか。","respondent":"立川保育課長","answer":"現在、聞くところによりますと、土地を取得してということではなくて、賃貸借をするというふうに聞いております。移転に関する助成に対しましては、経理的なところですけれども、現在ですと、国と都の補助等を利用して移転することができるということです。","voiceIndex":72,"id":"exchange-029"},{"speaker":"阿部委員","kind":"質問","question":"要は賃貸借で土地なり、プラス建物なりの賃貸借をして、かつ、国の補助金なり、安心こども基金などが活用できるのでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"既存保育園の移転につきましては、定員拡大と地域で抱える待機児解消に寄与するということであれば、国の補助金は安心こども基金により、来年度までの予算要求ができるです。","voiceIndex":74,"id":"exchange-030"},{"speaker":"渡部副委員長","kind":"質問","question":"今、０歳から２歳児を戸越六丁目でやっていて、平成２６年から５歳児まで受け入れるということなんですが、例えば５歳児から保育園に預けるということはなかなかそんなにいないのかなと考える中で、いわゆる転入希望というんですか、転園というんですか、そういう形でそういう世代を受け入れていくのか。例えば、エリアが本当に違うと思います。","respondent":"立川保育課長","answer":"現在、０歳児から２歳児までということで、移転後に４歳、５歳児のあきが出てくるということにつきましては、これにつきましては、ここから保育園を希望される方もそれほど多くはないので、仕上がって、子どもが持ち上がってくるまでは定員にゆとりがあるです。","voiceIndex":76,"id":"exchange-031"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"昭和通りおばちゃんちはオープンして１カ月、間もないので、今日も一人予約が入っていらしたけれども、キャンセルになったということなんですけれども、品川宿おばちゃんちのほうは、契約保育というのですか。","respondent":"伊崎待機児童対策担当課長","answer":"契約保育、一時保育とも時間で申しますと、料金は同じ５００円となっております。この契約保育の目的は、月極で短時間就労などを使う方について、席を確保しておくという意味合いから１カ月の契約という形をとっていただいているところです。","voiceIndex":83,"id":"exchange-032"},{"speaker":"南委員","kind":"意見","question":"毎月三、四名というんだけれども、例えば４月に入って１年近くとか、あるいは次の年の３月までとかという状況があるのかどうかを聞いたんですけれども。","respondent":"伊崎待機児童対策担当課長","answer":"こちらは月によってかなり状況が違っておりまして、例えばこの北品川二丁目の地区につきましては、昨年の４月に保育園が開設したという関係もございまして、昨年はあまり年度当初の契約保育でのご利用は少なかったと聞いております。","voiceIndex":85,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"今、途中で保育園に入られたりといった説明があったのであれなんですけれども、保育園に入れなかったときに、公立にしても、私立にしても、いわゆる認可保育園に入れなかったために契約保育という利用があるのかないのか、待機児がずっと出て、何年も続いているような状況なので、そのあたりのフォローになっているのかどうかということを知りたくて質問したんですけれども、そういう意味では。","respondent":"伊崎待機児童対策担当課長","answer":"だから、実際上は保育園に入れないからご利用されるという方がゼロではないということはありますが、ここ近年、保育園の開設も進めておりますので、そういったご利用は開設当初よりは減っていると聞いております。","voiceIndex":87,"id":"exchange-034"},{"speaker":"伊藤委員","kind":"確認","question":"この事業が、例えば２０年も安定してやっていけるような気も、もしかしたらないのかもしれないのがあって、そういうときにこの事業をどういうふうに担保していくのかなということが品川区の責任としてあるわけで、そういう契約はどういうふうになっているかということを確認します。","respondent":"伊崎待機児童対策担当課長","answer":"といいながらも、当然、開設のときは事業の継続性がある程度担保されるという実施主体者への確認はいたしてからやっております。今回も財政状況等々をすべて勘案しまして、２カ所目のオープンを認めたです。","voiceIndex":89,"id":"exchange-035"},{"speaker":"伊藤委員","kind":"質問","question":"そうすると、では、このサービスを提供したことについて、行政としてどう対処していくのかという新たな思いをするわけであって、そのことについて、なかなか答えにくいのかもしれないけれども、どこまで準備をしているのか、あるいはまた別な法人に移行していくなり、そういうようなことを行政として考えていく必要があるのではないでしょうかということをお伺いします。","respondent":"伊崎待機児童対策担当課長","answer":"２０年、３０年というスパンで見ますと、果たしてこの事業に対するニーズがどのように変わるかというところを今、お答えすることは非常に難しいところですが、法人の運営の健全性というところも含めまして、現在のところは。","voiceIndex":91,"id":"exchange-036"},{"speaker":"伊藤委員","kind":"質問","question":"なかなか、そうですよね。だけれども、万が一、運営主体のほうからそういう相談があった場合には、そういうことも賜った上で対処していってはいかがでしょうかということで、それは当然お願いしたいです。お願いします。","respondent":"伊崎待機児童対策担当課長","answer":"とはいいましても、今、伊藤委員のご指摘のような事態は想定されることもありますので、当然、そのときは区も法人任せではなく、実施事業の補助主体として、区民の方々に迷惑がかからないように考えていきたいと考えています。","voiceIndex":93,"id":"exchange-037"},{"speaker":"阿部委員","kind":"確認","question":"私もこのおばちゃんちの事業というのは非常におもしろいと思っていますし、ここに書いてある以外にもたくさんこの事業を展開されて、建設的にいろいろなことをされているので、注目すべき事業だと思っているんですが、ただ、こういうような対策について幾つか確認したいこともあります。運営実績なんですが、この平成２３年度の内容を見ていますけれども、時間で言えば何時間なんでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"利用の時間数が個々によってまちまちですので、合計の数字でご説明いたしますと、契約保育につきましては、日数ですが、平成２３年度は２６２日間の保育日数がございました。一時保育につきましては、６,３２３時間の年間の事業時間がございました。","voiceIndex":95,"id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"今後、この子育て交流ルーム、商店街をベースにしたもの、今後どういうふうに展開されていくつもりなのか、あるいはこうしたものはニーズがもしあるとするならば、商店街以外のところではどういう形で展開するのか、あるいは商店街以外で展開する気はないのか、そういった今後の考え方についてお聞きします。","respondent":"伊崎待機児童対策担当課長","answer":"ですので、前回もおばちゃんちしかできない地区でというわけではなく、今、広く地域の子育て、ＮＰＯをなかなかこういう手広い参入をしていただけるところが難しいということで、２軒目の昭和通りおばちゃんちをやったという経緯もありますので、ご希望のＮＰＯがあって。","voiceIndex":97,"id":"exchange-039"},{"speaker":"阿部委員","kind":"質問","question":"トータルの区としての持ち出し分を利用時間で割り返したら、実際はコストが幾らかかっているのですかという質問をしているのであって、１時間の補助は書いてあるのでわかります。その点と、それから基本運営費の積算の考え方について、どのようにお考えでしょうかということをお伺いしたいと思います。つくれるところしかつくらないんですかということをお尋ねします。","respondent":"伊崎待機児童対策担当課長、金子子ども未来事業部長","answer":"全体の経費ですが、平成２３年度の決算で９００万円余ということになっておりますので、申しわけありません。そういう芽のところに、例えば継続性であるとか、あるいは信頼性であるとか、さまざまな評価の観点から見たときに、的確な法人等々の実施主体があれば、それについては。","voiceIndex":99,"id":"exchange-040"},{"speaker":"高橋委員","kind":"質問・要望","question":"大変興味深い取り組みなので続けていっていただきたいんですが、もしわからなかったら後ほどでも結構なんですが、これはたまたま預かってもらう、今日は病気の子が来なかったということですけれども、紹介を持ってきたり、ある程度、配慮が必要な子も、まだこちらはそんなにないかもしれませんけれども、北品川のほうはそういった例があるのか、また、そういったところから、きっと相談があったりすると。","respondent":"伊崎待機児童対策担当課長","answer":"こちらは保育園と同じで健康なお子さんですので、病気の最中の病児保育としてのご利用はできない状況です。ただ、障害、特別な支援、配慮が必要な方につきましては、当然、園の環境上、お受けできるお子さんについては、相談をしていただいて、受けていただいているです。","voiceIndex":104,"id":"exchange-041"},{"speaker":"高橋委員","kind":"質問・要望","question":"区でそういった病気等で、他機関へつなげることが多いと思うので、その辺はまた確保していただけるとありがたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-042"},{"speaker":"阿部委員","kind":"質問","question":"開設に関しての補助金のことなんかを考えると、本来であれば、それぞれの区内でというのが一番理屈が通るのかなと思うんですが、その辺はどのようにされているんでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"地域開設につきましては、できるだけ区民の方をというお話はしております。ただ、直接契約ですので、最終的に契約をしますのはその施設の母体の事業者ということになってあります。","voiceIndex":110,"id":"exchange-043"},{"speaker":"阿部委員","kind":"質問","question":"認証保育所も駅に近いところを中心に、かなり、今日伺ったところも既にウエイティングが出ているような話だったと思うんですけれども、仕組みの問題というか、実態の問題というか、あれは別に先着順でなくても、ある意味、恣意的にといいますか、任意で入園者を選ぶことができる仕組みということで理解していてよろしいんでしょうか。","respondent":"伊崎待機児童対策担当課長","answer":"東京都の認証保育所の実施要綱で定められているものにつきましては、特に入所の規定はございません。保育が必要なお子さんを預かっていくです。ですので、事業所によって、その選考に基準が違うというところです。","voiceIndex":112,"id":"exchange-044"},{"speaker":"阿部委員","kind":"質問","question":"年齢なんですけれども、３歳以上について、国が来年度から補助のやり方を変えるという、それも理由のあることに対して言いますけれども、この一覧を見る限りでも、２歳までのところ、事実上、ほとんど２歳までのところとそうでないところ、いろいろあるかと思うんですけれども、この数字と、それからその他の、認可は当然、５歳までやっていて、あと、幼稚園等々は３歳。","respondent":"立川保育課長","answer":"年齢が上がるに従って、ある意味、認証から幼稚園なり、保育園なりに移る方がいるというところだと思いますが、その辺につきましては、現在、新規の認可保育園等の関係、その辺の関係につきましてはいろいろとありますので、その変更については、現在のところ。","voiceIndex":114,"id":"exchange-045"},{"speaker":"阿部委員","kind":"意見","question":"今のような話は、今後もまだ子どもの数も増えていくし、多分、保育園や幼稚園の数も上がるのだろうと思っているんですが、それが将来的にきちんとかみ合っていくような設計といいますか、発想で数字を考えていらっしゃるのか、考えたって、増えなければ向き合ってできないと思うのですが、もしかしたら、この先、この年代がきついという予測が立っているとか、そこまでは考えていないんだとか。","respondent":"伊崎待機児童対策担当課長","answer":"現在のところは、先ほど保育課長が申し上げましたように、新規開設の保育園での受け入れが続く、あとは既存の保育園での３歳、４歳、５歳の受け入れ枠について、どのようにすればいいかというところもありますので、現在、そういった見通しを持って進めておりますが。","voiceIndex":116,"id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"それと、これは多分、順番に１９園までずっと並んでいるんですけれども、設置年度によってずっと書いてあるんだろうとは思うんですけれども、この中でＡ型、Ｂ型の、伺うんですけれども、いわゆる保育園のみを運営しているところ、事業所としてしているのか、あるいは、それ以外の業務も兼業して保育のところもやっているのか、そういう事業所が１９園の中で何園ぐらいあるのかという。","respondent":"立川保育課長、伊崎待機児童対策担当課長","answer":"経営主体につきましては、１９施設中、個人の方が２施設、そのほかについては、ＮＰＯの施設につきまして２施設、それ以外につきましては株式会社という経営主体となっております。しながわがくどうえん、めだか保育園、ひよこの家保育園、こぐま保育園、ほかの事業者につきましては業態がさまざまですが、主に子育て支援事業や、あと保育事業などを行っているところが多うあります。","voiceIndex":118,"id":"exchange-047"},{"speaker":"阿部委員","kind":"質問","question":"先週の新聞を読んでいましたら、例のいじめ関係で、学校で新たにいじめが起きない環境をつくったりとかということがいろいろなところで紹介されていたんですけれども、そういうことというのは、どのタイミングで、教育委員会からのご報告があるとか、そういうことになるのか、どうなんでしょう。何か、どういう基準を持って選んでいらっしゃるのかということの考え方を含めて教えていただければ。","respondent":"太田指導課長","answer":"今後の対応策とか、当該校の対応については、昨日のお話に出ましたように、１月の文教委員会等でご報告申し上げるということですので、今、まとめているところです。","voiceIndex":133,"id":"exchange-048"},{"speaker":"阿部委員","kind":"意見","question":"それはそれで一つの考え方だと思うんですけれども、確かに情報を探してまとめてと、そのスキームはわかります。それは私の意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-049"},{"speaker":"南委員","kind":"質問・要望","question":"できないとか、調っていないというところまで報告しろなんて思っておりませんけれども、学校なり、教育委員会で努力をしているところはきちんとお伝えするということを前提で考えていただきたいと思っていますが、私はそう思うんですけれども、正副委員長にしても、そういう状況って、いつの時点でどういうふうになっているかってわからないところなので、そこを報告していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-050"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もちろん議員とすれば、その情報が欲しいことは確かなんだけれども、だけれども、このケースに限って言えば、一人の少年が自殺をされているわけだから、そのことに対して軽々しく委員会が中間報告をもとめていくというよりは、やはりしっかりとしたものを求めていって、責任ある回答があってもいいと私は思っていますので、それは私の意見で、そのように話をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-051"},{"speaker":"渡部副委員長","kind":"質問・要望","question":"今、その議論をする場ではございませんで、１月、２月、これからの委員会で、昨日お話ししたことがありますので、それで進めさせていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-052"},{"speaker":"阿部委員","kind":"質問・要望","question":"伊藤先生がおっしゃったことはわかります。副委員長もおっしゃっているんだと思います。事件の事実関係についての調査とか、そういったことを今、求めているのではないんです。そういったことは当然、デリケートに扱うべきだし、いろいろと疑問をまとめた形でご報告いただく、その路線で全く問題ないと思います。全然同意します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4778#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":37953,"voices":141}},{"id":"h24-20121127-5","meetingId":"h24-cm11","date":"2012年11月27日","dateIso":"2012-11-27","committee":"総務委員会","time":"午前１０時００分～午後０時００分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに(1)の「新地方公会計制度に基づく財務４表」","agenda":"はじめに(1)の「新地方公会計制度に基づく財務４表」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"読み解く力をつけていかなければいけないと思うのが１つと、あとは区民の皆さんに大切な区の財政状況をお伝えするのには、またそれなりにすごい努力が要るなと感じているのですけれども、私もホームページから２７ページ引き出したのですが、すごい量ですし、表がいっぱい載っていて、これは本当に勉強していかなければいけないと思っているのですが、まず１つは。","respondent":"本城企画財政課長","answer":"区民の方へのＰＲの関係ですが、こちらについては、まず、１番はちょっとさっきのご説明と重なりますが、広報ということで、今回のこの表とあわせて、そのほかの財政状況も含めて、今回で言えば、１２月２１日号でわかりやすい形でＰＲします。","voiceIndex":7,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"はじめの社会保障給付費などのところで、国民健康保険とか、あと、連結部分だと介護とか、この辺がかなり大きいとは思うのですが、一つは別紙３のところで、再開発４０億円と、かなり大きな額に入っているというあたり、この辺がこの団体への補助ですか。","respondent":"本城企画財政課長","answer":"連結の関係で、さっきは複数の構成団体が入っているときに案分するというお話でしたが、品川区のみが出資しているものについては１００％、この中に計算されて連結されているという関係です。","voiceIndex":9,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"再開発は上限があるということ、私はここに再開発が入っているので、意外だったので、こういう社会保障の。何か社会保障的な中身を含んでいるからこそ入れられているのか、ちょっとその位置づけが、ここに入るというところが何でかなという疑問があったので、そこを一つ続きでお伺いしたいのが１点です。","respondent":"本城企画財政課長","answer":"あと、他団体との比較ですが、今、総括の中でも概略、品川区の傾向ということで、指標だとか使いながら少しご説明させていただきましたが、それは２３区含めていろいろな自治体間もかなりこの総務省改訂モデルというものも結構使っているところ、かなり割合がありますので。","voiceIndex":11,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"三点目の、区政の傾向とか、この表から読み取ることができるのかというあたりを一点お伺いしたいのと、あと、もう１つは区民の方にわかりやすいということでは、広報と、あと、パンフレット３,０００部ですか、３,０００部はどこら辺にお配りになるのかというのも聞きたいですけれども、あと、詳細版をホームページに載せて、ある程度知識のある方にご理解をいただくということなのですけれども。","respondent":"本城企画財政課長","answer":"２３区等、ほかの自治体との比較ですが、今ご説明させていただいた範囲で申しますと、例えば、行政コスト計算書の中で経常収益が普通会計だと６８億５,０００万円ということでありましたが、それがどの程度独立になっているかとか、あるいは資産形成で、先ほど、品川区の場合。","voiceIndex":13,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"質問のお問い合わせとなっていると今、最後にお伺いしたのですが、お問い合わせってあるのでしょうか。できたら、双方向になると、より理解が深まると思うのですが、今のところいかがでしょうか。","respondent":"本城企画財政課長","answer":"一番多くの区民の方に触れるのが広報等の場面ですが、毎年せいぜい一、二件ぐらいのお問い合わせがありますが、そういう意味でよりわかりやすくする努力はこれから必要だと思いますが、必要に応じての対応はさせていただいていると考えているところではあります。","voiceIndex":15,"id":"exchange-005"},{"speaker":"石田（慎）委員","kind":"質問","question":"ちょっとわからなかった二点ほどお伺いしたいですけれども、まず、真ん中の期末資金残高ですが、これは普通会計と連結で、計算式というのですか、が違って、普通会計だと３８億円のものが連結だと２８２億円と膨らんでいる。これは何で普通会計は現金のみの計算で、連結になると、預金まで含んだ額を計上するようになるのか、説明をもう少ししていただければと思います。この二点、お願いします。","respondent":"本城企画財政課長","answer":"先ほどの資金収支計算書につきましては、こちらに対照した場合、かなり開きがあるので、その実際の開きということと違うのだという趣旨でご説明させていただいたのですが、なぜそのような計算式になっているか自体、ちょっと詳細は調べ切れていないものですから、ただ。","voiceIndex":18,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのですが、財務４表の増減額内訳、別紙３ですか。民間企業だと、例えば、機械を購入すると１０年で償却する。毎年３０億円ずつ黒字になって、先ほど、説明がありましたが、純資産も期末純資産の残高が実際前年度比較で１１６億４,０００万円増えているというのが説明ではありましたが、なかなかぱっと見て一般の人にはわかりにくいと思うのですが、その辺、どのように思われますか。","respondent":"本城企画財政課長","answer":"資産についてですが、こちらも資産の評価については、全ての施設について減価償却だとか、結果をあらわしているものではまだございませんで、先ほど、総務省の改訂モデルを使ったということでご説明させていただきましたが、総務省の改訂モデルのほかに。","voiceIndex":21,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、結局建物を建てたという資産、６０億円なら６０億円、そうすると、その資産としてずっとそれがここに残っていくという話になるのか。４０年、５０年ということで。そうすると、その前の額がそのまま残っているのか、それとも、昨日も何か話がありましたが、３年ごとに資産を見直しているのか、あるのですけれども、その辺について、もう１回教えてください。","respondent":"本城企画財政課長、日下部企画部長","answer":"この資産の評価の仕方ですが、この総務省改訂モデルというモデルで全ての自治体がこの財務４表をつくらなければいけないという関係になったので、割と資産の評価を厳密にしなくてもできるような形が今回の位置づけです。それを住民の皆さん方にも公表するというような仕組みとして提案し、それを受けて我々自治体が実施をしてきた経過というのが、今の官庁会計だけだと、よく言われますように、例えば、ストックの概念。","voiceIndex":23,"id":"exchange-008"},{"speaker":"大沢委員","kind":"確認","question":"確認。政策的な質問ではなくて申しわけないのですけれども、さっきの別紙２の負担割合のところでちょっとお伺いしたいのですが、純資産割る公共資産ということでやったのですけれども、１０４という数字がどうしたって出てこなくて、１０３としか出てこない。これ、どういうことなんでしょうか。","respondent":"本城企画財政課長","answer":"先ほどのもう１回、今の計算させていただきましたが、１０４.８ということで、割り算の数字がですね、純資産の額が９,２７８億円でございまして、それ割ることの公共資産であります８,８４９億８,０００万円。それを割るということで。","voiceIndex":28,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"確認","question":"いろいろご説明ありがとうあります。品川の財政の状況の部分がすごくよくわかると思います。だから、ここが何で、こっちは去年の表だと、分担金を載せてしまうと１０２億円ぐらいになるのですけれども、使用料・手数料だけ載せているから、何で変えたのかなというのをちょっと確認したいのですが。","respondent":"本城企画財政課長","answer":"別紙３のほうをちょっとご覧になっていただきますと、経常収益のところで６８億と。減の主なものが寄附金ということで。先ほど、ちょっと省略してしまって申しわけありません。","voiceIndex":34,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"行政コスト計算の中で区の方向性をどう出しているかというのも、この辺、数字を見ていけばわかる部分だと思います。確認、これ何なのというのはやっぱり言われることがあります。これからも、ぜひわかりやすく、また、人件費等も相当落としているのもこの中で出てきますし、改めて区のこれらの決算関係もしっかりやっていって、景気対策もとってやっていただきたいということをお願いして意見にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-011"}]},{"id":"topic-02","title":"の「第２０回品川区世論調査について」","agenda":"の「第２０回品川区世論調査について」","exchanges":[{"speaker":"石田（慎）委員","kind":"確認","question":"何で聞いたかというと、設問を見て、例えば、９ページの健康についてのところで、これを見る限り、自転車の利用とか、そういうことが１つも書いていないというのが非常に区の思いが反映された設問ではないかなと非常に見受けられるので、そういった部分に関して、例えば、彼らは委託先の会社のことも、調査を専門でやられている方たちだと思いますので。","respondent":"荒井広報広聴課長","answer":"個人情報の取り扱いについては協議書を交わしまして、それに基づいて行っているところですが、訪問するわけですので、個人情報を持っていくような場合があるかと思いますので、それにつきましては。","voiceIndex":43,"id":"exchange-012"},{"speaker":"阿久津委員","kind":"質問","question":"今、いろいろ先に聞いていただいたので、質問しなくてもよかったのですけれども、お聞きしようかどうかを迷っていたのですが、定住意向が今回このアンケートの一丁目一番地で非常に重要だと思うのですけれども、過去最高になったということなのですが、９１.５％ということで、ちょっと参考までにここ３回ぐらいまでの定住意向の何％だったというのをまず教えていただけますか。","respondent":"荒井広報広聴課長","answer":"１８回ですから、これは平成２０年に実施したときは８８.９％です。それから、１９回ですが、１９回のときは８９.７％です。","voiceIndex":46,"id":"exchange-013"},{"speaker":"阿久津委員","kind":"意見","question":"非常にというか、これも非常に違いがある、非常にという違いかどうかあれなのですけれども、品川区の場合はずっと住みたい５３.８％とここに書いてあるとおり。当分は住みたい３７.７％、この２つをあわせて９１.５％。東京都のほうは、今日調べてきたら、住みたいという設問と住みたくないという設問で分かれていまして、住みたいという設問だけだと７５.７％。","respondent":"荒井広報広聴課長","answer":"あらましのところでは、この定住意向という形でしか出していないのですけれども、今後、本書の報告書の中でライフステージ別であるとか、それから継続して住まわれている方とのクロス集計などがありますので。","voiceIndex":48,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"回収率が７５.６％と、今年はかなり高いなと思っています。この辺の受けとめ方と今、いろいろな面で国勢調査なんかも入りにくかったり、大変な中で工夫がされているのかなと思うのは、お伺いしたいのが一点と、あと、やはり、なかなか区政について知ってもらうという機会がない中で、ここに答えてくださる方というのはかなり関心が高まる傾向にあると思うのですね。","respondent":"荒井広報広聴課長","answer":"項目の選び方についてですが、ご説明させていただいたところと、それから議員ご指摘のとおり、経年的に見るべきものが幾つかということで絞らせていただきまして、そのほかの何度かに１回、例えば、区議会の項目もそうだったと思うのですが、２回に１回というのですか。","voiceIndex":51,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"意見","question":"１つだけ、４ページのところの防災のところは初めて聞いていて、私は今すごく重要だなと思っているのですが、ちょっと項目が寂しいなと思ったのが一点あったので、今後充実すべき防災対策のところで自助・共助、公助に分けてあるのですが、項目がすごく少ないのと、共助のところの思いを書くところが何も項目がなかったのですが、項目ってここに載っているのはそのままなのですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":53,"id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"品川区の世論調査あらましということで、回答率、回収率、それからバランス、そういう別もそうですが、年代別、本当にすごいなと。ただ、そうすると、冊子のちょっと枚数、ページ数にもそれぞれ限りがあると思うのですが、せっかくこうやってバランスよく回答を得られるならば、そういうのも見られるとありがたいなと思ったのですが、その辺、前も何かそのような質問、また、何かご検討とかしたのでしょうか。","respondent":"荒井広報広聴課長","answer":"年代別についての集計の件なのですけれども、あらましのほうにはあくまでも単純集計ということでご理解いただいて、あと、報告書のほうに、間もなくでき上がるのですけれども、そちらのほうに年代別等がありますので、ご覧いただくという形でご理解ください。","voiceIndex":55,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"確認","question":"９１.５％の方が住みたいということで、やっぱり品川区に対する期待がこれからも大きいのだなという中と、議会の関心が低いというのは一つ我々として寂しいということをすごく感じています。項目的に確認したいので、表紙の中で調査の内容の項目なのですけれども、これは毎回同じなのでしたっけ。ちょっと前回のを調べてこなかったので、大体が同じふうなことだと捉えていいのですか。","respondent":"荒井広報広聴課長","answer":"上から１、２と、それから１０につきましては継続的に調査しておりますので、同じ項目です。そのほかの項目につきましては隔回ごとであるとか、何回かに１度とか、長期基本計画などについては今回、前の長期基本計画の時以来とか、そういうような形で設定しています。","voiceIndex":58,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"意見","question":"これは全体的には商店街というか、商店街だったら商店街がやるべき部分かなという思いで。区がここに限定する、だから、中小企業とか商店についてとかいう項目だったら、区がやる部分かなと思うけれど、ちょっと限定がついているような気がしたのですが、その辺どうかなと思います。","respondent":"荒井広報広聴課長","answer":"一つは、長期基本計画にあります「にぎわいあるまち」の関係で項目を設定させていただいたということと、それから商店街調査というのを区商連と地域振興事業部の商業・観光課と一緒に実施したところなのですが、そちらのほうが商店街に特化した調査だったものですから。","voiceIndex":60,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"やるのがおかしいというか、ニュアンス的な感覚でにぎわいという、区としてはにぎわいの部分がメインですよね。これはちょっと特化し過ぎているかなというふうに私は感じます。中身がいい悪いではなくて、何か気になっているところが一点。それから逆に今回選ばなかったのかもしれないけれども、教育関係というのは、今まで、前回なんか、教育に関してはありましたか。","respondent":"荒井広報広聴課長","answer":"教育に関する項目というのはあまりとらない傾向があります。どちらかというと、子育て環境ということでとらせていただくことが多くなっているというふうに記憶しております。","voiceIndex":62,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そこら辺が区としてどう、その辺抜きでいいのかというのがちょっと感じたところです。これの中で、これだけの回収できた中で、２番の生活環境については評価できる部分ですとか、それから重点施策の中でポイントの大きい部分、これに区としてどこかに出していただいて、施策に活かしていただきたいということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-021"}]},{"id":"topic-03","title":"の「平成２４年１２月１６日執行 東京都知事選挙執行要領および衆議院議員選挙・最高裁判所裁判官国民審査について」","agenda":"の「平成２４年１２月１６日執行 東京都知事選挙執行要領および衆議院議員選挙・最高裁判所裁判官国民審査について」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"そういった面で、区役所とあと地域センターの投票所のところで十分その辺が見られるのかどうかという質問なんかも受けたので、ちょっとそこのところをお伺いします。","respondent":"諸岡選挙管理委員会事務局長","answer":"そうすると、せっかくお見えになっても都知事選挙はできても、衆議院はできないで、またお越しいただくということになると、非常に混乱が起きるので、むしろちょっとおくれたのが、そのほうが混乱は少ないのかなという感じはしております。","voiceIndex":69,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういうこと。今気づきました。投票のやりやすさというか、清き１票なので、どなたの１票も本当に投票したいという思いができるだけかなえられるというところにおいて、現行の期日前とか不在者のところの改善を求める声もあるのですね。目の前にあるのに、坂を下っていったり上ったりしないと、投票所に行かれないという方に対して何か改善策はないかと思っているのですが、いかがでしょうか。","respondent":"諸岡選挙管理委員会事務局長","answer":"そういう意味で、投票区ごとに分けさせていただいているという実態がございまして、今、機械的には可能であるかどうかといわれれば、それは地域変更もできるわけですので、当日も機械上はチェックはできるわけですけれども、そういった混乱を来すようなこともあるということで。","voiceIndex":71,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"検討がいろいろ要るかと思います。機械的な面ではきっと多分お金をかければできるのだろうと思うのですが、財政面もいろいろあると思うのですが、そんなにたくさんいらっしゃらない、やっぱり不便で何とかしてほしいという部分も受けとめるというか、実際にどういう状況なのかというのも調べていただいて、前向きに検討していただけたらと思いますけれども、いかがでしょうか。","respondent":"諸岡選挙管理委員会事務局長","answer":"身体障害者の方の施設もそのようなことで投票できるようなところも登録されておりまして、かなり増えてきておりますので、そちらのご活用もお勧めいただければと考えています。","voiceIndex":73,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"特養ホームとか病院とか施設で受けとめていただいているところにいらっしゃる方はいいのですよね。その制度からはみ出ている部分で、やはり投票をしたいのにできない、投票したくてもできない方が在宅でいらっしゃるというところを受けとめていただきたいということなので、ぜひ検討の中に入れていただきたいと思います。別問題ではないですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ということで、ざわざわしないでいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"確認","question":"投票所の中で、建物の中で部屋が変わるのは、十分誘導できると思うのですけれども、今回、投票所が変わるということで、これは地域の方はやっぱり今まで行っていると、どうしても前回と一緒だと思ってしまう。もう広報紙に出ているのは知っています。場所が変わりましたは出ているけれども、そこまで見ていないで。投票券の中に何か表示はあるのでしたか。そこら辺の確認をちょっと。","respondent":"諸岡選挙管理委員会事務局長","answer":"選挙区ごと。それから当日も、浅間台小学校に間違って行ってしまわれる方も多いと思いますので、近くの交差点あるいは学校の前のほうに人を配置して、混乱のないようにご案内できるようにさせていただきたいと考えています。","voiceIndex":78,"id":"exchange-027"},{"speaker":"鈴木（真）委員","kind":"意見","question":"あそこはちょうど坂の途中で、坂を下りてしまってまた上ってくるとか。そこに行ってしまえばわかるのだろうけれども、その辺も、やっぱり地域の人に聞かれるので、その辺ぜひ対応よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":80,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1932#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":39351,"voices":85}},{"id":"h24-20121128-14","meetingId":"h24-cm11","date":"2012年11月28日","dateIso":"2012-11-28","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時３０分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"旧西五反田職員待機寮跡地の売却","agenda":"旧西五反田職員待機寮跡地の売却","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ちょっと伺いたいんですけれども、一般競争入札ということですけれども、入札に参加する基準というのはあるのか、個人でもいいのか、会社でいいのか、会社でも何か業務とか、そういうところに一定の基準があるのか、そこを伺いたいと思うのと、資産としては相手に渡るとなると、その後の活用というのは全くのフリーハンドになるのか、それとも、この間の議論で周辺の方々から。","respondent":"平澤経理課長","answer":"こちらにつきましては、地方自治法施行令第１６７条の第４項第１号に該当する者は参加できないということで、いわゆる禁治産者等、そういうのは参加できません。個人については、可能となっています。は指名停止中の者も当然参加できないということになります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"売却した後の使い方について、反社会的勢力への制限というご説明でしたけれども、それは当然だと思います。要するに、建て替えるのか、それとも既存のまま改修して使うのか、それとも補強して使うのか、そういうところは相手方が決めるということになるのでしょうか。そこだけ伺いたいです。","respondent":"平澤経理課長","answer":"所有権が移転されますと、それは先方のご判断ということになると思います。","voiceIndex":7,"id":"exchange-002"},{"speaker":"須藤委員","kind":"質問・要望","question":"前にも言ったように、売却するにもちょうどいい時期で、こういう数字が出てきたんだろうと思うんですが、３億４２０万円というこの金額を入金させて、その後、一般会計にそのまま行って、普通に使ってしまうのか、今後こういう公共施設を処理した場合のお金の基金ができ、こういうふうにプールして、次に使っていくとか、そういう仕組みを考えていらっしゃるのか、単に一般収入として使っていってしまうのか。","respondent":"日下部企画部長","answer":"ケース・バイ・ケースということもありますけれども、基本的にはそのような考え方に立っております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須藤委員","kind":"質問","question":"せっかく有効活用という意味できているので、それが見えなくなるのではなくて、こういうふうに活用されていますというのを、我々が区民に説明できるような仕組みをつくっていただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"西本委員","kind":"意見","question":"入札申し込み者が８社で、参加者が４社、この４社の方の辞退はどういうふうになっているか。","respondent":"平澤経理課長","answer":"こちらにつきましては、売却なので、工事とかそういう入札ではございませんで、売却ということで、買い取りのことですので、何らかの会社のご事情もあったということで、その辺は承知してございません。","voiceIndex":12,"id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最低入札価格が１億８,０００万円だったと思うんです。それで、３億４２０万円というのは、異様に高いと私は思っております。一番下はどうでもいいんだけれども、２位ぐらいの金額は教えていただきたいのと、この３億４２０万円は、すごく乖離があるような気がしてならないんです、２位との方と。","respondent":"平澤経理課長、日下部企画部長","answer":"予定価格の１億８,０００万円との乖離ですが、予定価格につきましては、財産価格審議会で答申をいただきまして、それに基づいて決定させていただいるところです。売却益の活用ですけれども、確かに当初の見込み以上の金額が入ることになるわけです。","voiceIndex":14,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"意見","question":"これは私の感想ですけれども、この委員会で、消費税の法案が通った以降、土地は異常に上がっているなと思っています。やっぱりそんなもので、時機を見据えて、公共的なものもこれから、これだけではなくて、ほかの次の段階もあると、でしたら、やっぱり時機をしっかりとらえていくことも考えていくべきだと思うので、それだけはよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-007"}]},{"id":"topic-02","title":"の２、特定事件調査","agenda":"の２、特定事件調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"やっぱりこの間の経過を見ても、もっと丁寧に進めるべきだったと私は率直に思います。パブリックコメントをかけるものとかけないものと、どういう判断があるのか、それぞれ今まで利用された方々、周辺の方々にとっては、愛着のある施設でありますので、一つ一つ住民参加を位置づける姿勢が必要ではないかと思うんですけれども、ここを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"ただ、平成１８年６月の終わりから８月１５日まで１月半以上、ホームページではありますけれども、周知をいたしまして、意見を募集したといった経緯がございまして、制度はなかったんですが、先駆け的なことは行ったということは言えるかと思います。","voiceIndex":23,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"パブリックコメントをかけるかかけないかは、恒久的な利用か、一時的な利用かで分かれるというご説明でよかったのか、もう一度確認させてください。となると、旧第一日野小学校、あと旧荏原第四中学校は、どちらもいわば暫定的、一時的な貸し付けということですが、本格的にこうしていきましょうとなった時点では、パブリックコメントをかけるということでよいのか、改めて伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"現段階では、具体的な内容につきまして、まだ設計をしている段階ですので、こちらにつきましては、まだそういった形でご意見を聞くタイミングではないと考えています。","voiceIndex":25,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん議会にも報告していく、そういう仕組みが必要ではないかと思うんです。最近では、旧第一日野小学校は、当初計画から変わったということで説明は実施いたしましたが、そのほかについては、地域住民の事業説明会をかたくなに拒む、その姿勢を改善していく必要があるのではないかと思うんですけれども、その考えを伺いたいと思います。","respondent":"柏原行財政改革担当課長","answer":"それ以外のものにつきましても、先ほどいろいろ細かくはお話しできなかったんですけれども、地元の方とか、町会の関係の方、もちろん区議会もそうですけれども、地元の方の意見調整や説明会やお話し合いというのは、数としてはかなりやってございまして。","voiceIndex":27,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば、この旧原小学校のときでも、旧八潮の小学校、中学校のときでも、町会長や地域の住民の代表の方々、商店街も含めて、いろいろそこで説明していることは伺っています。ぜひそこをやっていただきたいし、そういう仕組みづくりそのものも、この際しっかりつくるべきだと思うんですけれども、改めていかがでしょうか。","respondent":"日下部企画部長","answer":"ですから、その辺のやり方は、それぞれのケースによって違いはありますけれども、私どもは何もすべてがすべて拒んでいるわけではありませんで、それは適宜対応しているということでご理解をいただきたいと思います。","voiceIndex":29,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"今パブリックコメントという形でそこをやってはいるけれども、どういう計画なのか直接説明を聞く場がないという話をよく伺うんです。つきましては、最後決定するに当たって、地域の住民の方々に説明をして、ご意見を求めていくと。意見を直接言う、説明することを聞く場を設けていく、そういう仕組みが必要ではないかと思うんですけれども、最後の部分を改めて伺いたいと思います。","respondent":"日下部企画部長","answer":"ですから、一概にどういう形でということではなくて、さっきも申し上げましたけれども、その区有地、あるいは跡地、跡施設を取り巻く立地条件とか、地域特性とか、そういうものに応じてやりとりをする、これが一番いいと考えていますので、これからもそういう意味では。","voiceIndex":31,"id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"こみゅにてぃぷらざ八潮の使用率はどのぐらいに上がってきているんですか。","respondent":"日下部企画部長","answer":"ただ、もう一つ、部屋によってあそこは多目的に、例えば、ダンスなどで使える、あるいは音楽で使える部屋がありますけれども、そういうところはかなり人気がありまして、普通の会議室なんかよりも利用実績は上がってきているということで報告を受けております。","voiceIndex":33,"id":"exchange-013"},{"speaker":"須藤委員","kind":"質問・要望","question":"そうすると、活用されていないということは、資産が有効に使われていないという話になってきてしまうと思う。そうではなくて、やはり区民ニーズを、行政自身がしっかり方向性を捉えて、そこでこういう形になるので、区民の皆さんとそれをどうやって活用して生かしていくんだという話し合いを進めていっていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"防災の観点でいろいろなものが、防災広場とか、そういったものも必要なのかなというのも需要として、需要というか、必要な政策としてといったほうがいいのかもしれないんですけれども、あるのかなと思うんですけれども、そのほかに、その他も含めて、区としての行政需要、出てきた跡地について、どう利用しようかというところでの重点的な視点、プライオリティー。","respondent":"日下部企画部長","answer":"備蓄をどうしていくのか、そういうことも含めて、非常に重要な課題だと考えています。私どもとしましても、高齢者への対応、それから防災関係、この辺が今特に重要な課題だということで、同じ考え方です。","voiceIndex":36,"id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"話が少しそれてしまうかもしれませんけれども、今マスコミなんかで国家公務員の宿舎を半減させるということで、売却していくということで、品川区にもどうやらそういうのが８施設あって、売却していく、廃止していく予定、２０１６年までということで、比較的短い時間かなと思っているんですけれども、すぐに区に売却という話には、一直線にはならないかと思いますが、この辺について。","respondent":"柏原行財政改革担当課長","answer":"ただ、それが出たからといって、即座に何かするかというのは、行政需要とか、先ほども地元の声とかいろいろお話がありますので、そういったところを踏まえながら、多角的な検討をしなければいけないという考え方です。","voiceIndex":38,"id":"exchange-016"},{"speaker":"塚本委員","kind":"意見","question":"わかりました。先ほどの行政需要をどういうプライオリティーでというところも含めて、この件に関してもしっかりと対応していただければと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":40,"id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"提案","question":"だけれども、先ほど最初に言ったようなことに関して、これはこれぐらいでセーフティーネットにしておけとか、みんな思いながらやっているわけであって、それを、１００％あるようなことを言っておけば、それはまさに選挙活動みたいなことをしている人、そういう方々の意見は、今度行政側もしっかり、それはそういうことでしょう、十人十色意見はあるけれども、行政側だって、１０人に意見を聞いたら。","respondent":"日下部企画部長","answer":"そういうことで、とにかく議会にはご相談しますけれども、これからまた検討を進めていきたいと考えていますので、ご理解いただければと思います。","voiceIndex":41,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうしたら、学習塾というので、４部屋を充ててあると。平成２３年２月にオープンしたわけでしょう。あえて私は、若い子のそういうところをつくるのでなくて、戦略的にそういう方向に向かうべきだと私は思っていて、そういう部分の模索をぜひしていただきたいと、要望にしておきますけれども、こういうことはぜひ、この後またやりますが、ぜひないようにしていただきたい。それはちょっと意見。","respondent":"日下部企画部長","answer":"ほかにもあるんじゃないかというご指摘ですが、私どもも、これはもう当然行財政改革特別委員会で施設の有効活用という観点でご審議をいただくということも含めて、区としていろいろ貸し付けをしている施設も含めて、今回のこみゅにてぃぷらざ八潮はその点どうなんだと言われると。","voiceIndex":43,"id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"高齢者を集める政策をしていくという考え方、あそこの住宅については、法律の位置づけを変えろということをやっていくのか、それはもう一時期そんな話をしたんだ、特区をやってしまうとか、それは外さなければいけないとか、いろいろな話をしたけれども、それは大きな話になってくることも含めて、私は外から集める、集客スペースを八潮の中にぼおんとつくるより、八潮のあの環境を考えたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"協働というのも、品川区としては打ち出しているところでもありますので、本当にこういう公有地については、協働で運営していく、意見交換もきっちりしていく、かぶることはきっちりかぶっていく、理解を示していくというような、住民の意識改革というんですか、大変ですけれども、反対ばっかりではないというところもこれから必要なことではないかと思うんですが、例でいうと、こみゅにてぃぷらざ八潮と。","respondent":"日下部企画部長","answer":"ですから、現状としては、区の施設として運営しているということなんです。その当時自治会の各会長方が結構中心になってご検討いただいた経緯もありますし、自治会ですから、結構会長がかわるケースというのが多いんです。","voiceIndex":46,"id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"何でだめなのというところ、あとは行政からも、行政ニーズでの特別養護老人ホームの設置など、いろいろなことがあると思うんですけれども、そういうのを根拠もきっちりと示していただいて、その中での役割分担というのははっきりやっていかないと、建設的な意見以外は聞く必要がないというぐらいに私は思っていますので、品川区にとってというところは皆さん同じだと思うんです、行政側も行革もやるにしても。","respondent":"日下部企画部長","answer":"あるいは地域によっては、なかなかそこまではいっていないとか、それはそれで、地域によって、あるいは施設を取り巻く環境といいますか、それぞれかなり違いがあると思いますので、大事なことは、協働という言葉は１つですけれども、すべてが一律ということではなくて。","voiceIndex":48,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"この行財政改革委員会に前かけられた四中跡地の請願なんですけれども、今日はご報告してくださいとは言いませんけれども、要するに、その後どういう状況なのか、どんなふうになっているのか、次回以降でも、若干の経過説明があればと思いますので、ご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5936#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":29990,"voices":56}},{"id":"h24-20121129-17","meetingId":"h24-cm11","date":"2012年11月29日","dateIso":"2012-11-29","committee":"震災対策特別委員会","time":"午前１０時００分～午後２時５７分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"学校避難所マニュアルなんですけれども、今回、地域防災計画が改訂されますけれども、これに伴って、学校避難所マニュアルのほうで何か反映されるようなものというのがありましたら、教えていただきたいんですけれども。学校避難所マニュアルを改訂していくという方向性とあわせて。","respondent":"高山防災計画担当課長","answer":"その１つとしては、後ほどご説明いたしますが、東日本大震災の際にも課題となりました女性への対応、そういった、いわゆる弱者への対応の部分について、現行の標準的なものについては淡泊な記載になっておりますので。","voiceIndex":7,"id":"exchange-001"},{"speaker":"武内委員","kind":"質問","question":"女性の関係と弱者の関係は何となくわかるんです。水ですか。そこら辺はどんなことか、教えてください。","respondent":"高山防災計画担当課長","answer":"水につきましては、さまざま生活に使う水、そして飲用の水などがありますが、水を使うにしましても、例えば、第一義的には応急給水槽などの学校備えつけのものでありますとか、あるいは消火栓等が生きていれば、そういったところからのスタンドパイプによる供給でありますとか。","voiceIndex":9,"id":"exchange-002"},{"speaker":"武内委員","kind":"質問・要望","question":"５ページですか、この救護所なんですけれども、各地区に１カ所ずつぐらいあるという認識なんですけれども、それで、この救護所で救護をする、手当てするというのはどの程度のところまでされるのかということと、あと、もし救護が必要な方がほかの避難所から来た場合に、そこで救護が終わった後に、手当てが終わった後に、また自分の割り当てられた避難所の学校に戻られるということを想定しているのか。","respondent":"高山防災計画担当課長","answer":"したがいまして、先ほど委員からもお話がございましたように、医療救護所のある避難所以外からの利用についてということで考えますと、各学校にも、いわゆる応急セットのようなものはありますので、その範囲で対応できるものについては、当然。","voiceIndex":11,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"学校避難所連絡会議が平常時から打ち合わせをしているということなんですが、これは定期的に行われているのかということを１つお聞かせいただきたいと思います。それと、学校避難所マニュアルは学校ごとにできているということなんですが、すべての学校でこれができているんでしょうか。できているとしたら、一般の区民もそれを見ることができるのかというあたりがどうなっているのかを教えてください。","respondent":"鈴木防災課長","answer":"そのうち３割ぐらいが参集できるだろうという想定で、三、四人の区職員が避難所に参集できれば、地域の方、また学校教職員と力を合わせて運営ができるだろうということで想定しているものです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、あと先ほど学校の耐震化の状況というのはご報告いただいたんですが、私が気になっているのは避難所のトイレなんですが、これも改修を年間５校ずつですか、されていると思うんですけれども、もう改修ができた学校がどこなのか、それから、今後どういうふうに改修をされていく予定なのか、お聞かせいただきたいと思います。","respondent":"鈴木防災課長、齋藤庶務課長、武藤河川下水道課長","answer":"あとペットについても、ちょっと考えたほうがいいねという意見、それから、あとは限られた空間で多くの方が緊張、ストレスの中で生活をされるので。おおむね５カ年で完了の予定ですが、若干学校の施設と道路との勾配の関係もあって、全校でできるかどうか、できるように頑張りたいと考えていますけれども。避難所等につながる下水道管の耐震化につきましては、区で一部受託して事業を促進しまして、一応、来年度で避難所等。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、学校のトイレが１階のトイレ１つだけの耐震化というふうなことでお聞きしたんですけれども、そうすると、それはトイレとしては何個ぐらいあるものなのか、お聞かせいただきたいのと、それは学校のトイレを全部、少なくとも１階はすべて使えるとか、何カ所かトイレがあったら、そのトイレが全部使えるようにとか、そういうところに、できればその建物全体の水洗トイレが使えれば。","respondent":"鈴木防災課長、武藤河川下水道課長、齋藤庶務課長","answer":"それと、もう１つはプール、それから学校に生活用水用の浅井戸もありますので、その水をポンプでくみ上げたりして使うという方法もありますので。公道の下水道管の耐震化につきましては、下水道局では、一応、さまざまな可能性も考慮しまして。一番公道に近い１カ所とそのトイレ１カ所を結びつける、男子トイレであれば、大が２つ、３つ、小が幾つか。","voiceIndex":19,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう中で、トイレというのは何人に１カ所は整備していこうみたいな、そういうふうなものというのはないんでしょうか。それがすごく阪神・淡路大震災のときにもかなり大変な状況だったということが出ていましたので、そこのところは何人に対して１カ所のトイレというふうなところを目指して整備をしていくという考え方は必要なんじゃないかと思うんですけれども、いかがでしょうか。","respondent":"鈴木防災課長","answer":"使い捨てトイレですが、清掃事務所の清掃回収作業は比較的、いわゆるバキュームカーによるし尿の回収よりも早く機能が回復するということがありますので、そちらの方法であれば、それぞれトイレを使用した後に、それを密閉したごみとして集めておいて回収すれば。","voiceIndex":23,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、１カ月で復旧して、それで、自宅があって帰れる方はいいと思うんですけれども、一応、この被害の想定では２万１,５００棟ぐらいが火災で焼失するという想定が出されていますけれども、そういう方は仮設住宅ができる状況にならないと、なかなか避難所から出られないという状況もあると思うんですけれども、そこら辺の見通しというのがどうなっていくのかをお聞かせいただきたいと思います。","respondent":"鈴木防災課長","answer":"具体的に、災害状況によって何日間で何人、どこに行くということは計画でうたえるものではございませんので、状況に応じて、できるだけ避難者の方の少しでも日常に近い健全な生活を維持できるような対応をするというのが計画の考え方になっております。","voiceIndex":25,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"東日本大震災のああいう地域であっても、仮設住宅をつくるというところはすごい大変だったと思うんですけれども、そういう点では、この都会の中で、品川区の中で仮設住宅を、しかも多分、２万１,５００棟消失すると言われているところが荏原地域のほうに集中するのではないかと思うんですけれども、そういうところになったときに、仮設住宅をどう確保していくのか。","respondent":"松代防災まちづくり事業部長、高山防災計画担当課長","answer":"そういった中で、１日目、２日目というような時間的な経過がしたときに、避難された方々へのまず１日目の対応というところは、そういった食糧だとか、どういった配分をしていくのかとか、いろいろと細々したことがあり、かつ。毛布の件だけ補足しますと、委員から倍というようなお話だったんですが、おそらくアルミパックをすることで収容量が倍にできるという、そのような趣旨でご説明させていただいていたことかと思います。","voiceIndex":27,"id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっとばらばらになってしまうかもしれないんですけれども、教室の割り当ての表示なんですけれども、多くできているところも学校に行って見せていただいているんですが、これはすべての学校にもうできているのかどうかということを１つ確認をさせていただきたいと思います。","respondent":"齋藤庶務課長、鈴木防災課長","answer":"その他運営にかかわりましては、もちろん学校設置者である区長、その下にいる教育委員会事務局の校長以下ですので、学校の様子が一番わかっておりますので、教室をあけたときに机をどこに片づけるだとか、備蓄倉庫をどうするとか。これにつきましては、ご存じのように、通信のインフラ、要は電話回線が生きているかどうかということにも、それから電源がないと使用できませんので、その辺の状況にもよりますが、必要に応じて、区のほうで、本部で配備する無線だとか。","voiceIndex":31,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"避難の表示なんですけれども、これは避難所連絡会議が機能していれば、すぐにどんどんついていくんだろうなと思うんですけれども、まだ全部ではないというところでは、きちんと全部必要だと思うんですが、そういった経費が学校の教育費から出さなければいけないとなると、遅れてしまうのかなと思うんですが、その辺、１００％にするのをどの辺の目標に、それは学校なのか、防災課なのか。","respondent":"鈴木防災課長","answer":"ただ、いつ災害が来るかわからないので、やっておくといいだろうねということで、学校のほうの判断でやっていただいているもののようですので、今後は教育委員会とも相談させていただいて、どのような対応をするかということは検討させていただきたいと思います。","voiceIndex":34,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問・要望","question":"今のでいくと、学校のほうは仮になってしまうと、地域の方も保護者が参観に行ったり、学校に行く機会はありますので、そこはふだんからそういうところだということを防災意識の自助の向上にもつながるので、ぜひ学校のほうで積極的に働きかけていただく、副校長先生をはじめとして連携をとるということなので、そうしていただきたいと思うんですが、そのことについていかがでしょうか。","respondent":"齋藤庶務課長","answer":"今、防災課長からご答弁申し上げましたとおり、私どもも防災課と十分協議して、対応させていただきたいと思います。","voiceIndex":36,"id":"exchange-012"},{"speaker":"大沢委員","kind":"質問・要望","question":"学校避難所マニュアルの概要の４ページの災害時の対策、共通ルールの(3)のところということで、今、課長から、いつ災害が起こるかわからないというようなこと、まさに当たり前のことなんですけれども、そこの中で、校長室、職員室、理科室等、施設を管理する上で必要な部屋または危険な部屋は宿泊させない、宿泊をさせないのは当然のことなんですけれども、災害時になって、ここが避難所となった場合。","respondent":"和氣学務課長","answer":"劇物・薬物に関しましては、専用の金庫、保管庫を用意してありまして、施錠して管理しています。そういう理科準備室等については施錠して、通常は誰も入れないような形で管理しています。","voiceIndex":38,"id":"exchange-013"},{"speaker":"大沢委員","kind":"質問・要望","question":"そこのところ、施錠管理されているということですけれども、これは災害のときにどのようなことが起こるという可能性もなきにしもあらずなので、そこのところが頻繁に、月に何回ぐらいの程度でそれは管理をされているのか、学校管理者の方が、校長、副校長が現認のもとにそれを管理されているのか、それとも担当の理科の教員が管理をされているのか、どちらかを教えていただきたい。","respondent":"齋藤庶務課長","answer":"その鍵の管理は理科の教員が実施しておりまして、薬品を使った場合、何を使ったか、どれを使ったかということを帳簿につけて管理をしておりまして、日々管理をしている、校長にもそれを報告するといったことで。","voiceIndex":40,"id":"exchange-014"},{"speaker":"大沢委員","kind":"確認","question":"そうすると、最終管理者は校長が管理をされる、こういうことで、管理者である校長、あるいは副校長が最終的には確認するということの順番でよろしいんですか。","respondent":"齋藤庶務課長","answer":"委員ご指摘のとおりです。","voiceIndex":42,"id":"exchange-015"},{"speaker":"阿久津委員","kind":"質問・要望","question":"これに関して、私も仕組みがよくわからなくて、これは全国的に統一されているものなのかどうかというところもあるんですけれども、昨年の３・１１のときに、当時、私は議員ではなかったんですが、いろいろな方から、東北にゆかりの方から、ご自分の親戚の方とか、お身内の方が行方不明になったというようなご相談をたくさん受けまして、調べようがなくて。","respondent":"鈴木防災課長","answer":"件数も多いですし、回線もどこまで生きているかということになりますので、基本的には、今後、お話しするときにお願いするのは、ＮＴＴの１７１、災害伝言ダイヤル等、個人のご家族等の安否確認については一般的な手段を使っていただいて、本部のシステムについては。","voiceIndex":44,"id":"exchange-016"},{"speaker":"阿久津委員","kind":"質問","question":"ちょっと私自身が勘違いをしている部分もあって、役割分担というところではよくわかりました。そこまで詳しくは教えていただけなかったと確かに覚えているんですけれども、ここら辺の仕組みを私自身ももうちょっと考えてみたいと思います。ペットのことについては、また後ほど地域防災計画のところで伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう方から、福祉避難所が設置されて初めてほっとしたという声もすごくお聞きしたんですけれども、ここら辺のところの対応がどういう体制でされるのかをお聞かせください。","respondent":"高山防災計画担当課長","answer":"１つの役割分担の中で、例えば、いわゆる地域の方々の力もかりながら運営をしていきませんと、専門的な知識の方が必ずしもそこにいるとは限らないという中で、役割分担をしながら、少しずつ負担感を分散して、いわゆる全体の中で補っていただくといった、その趣旨のものですので。","voiceIndex":47,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"何かどこかの本で、そういう地域の中でも、そういう医療的な資格を持っている人をきちんと把握して、こういうところに名簿としても連ねておいて、いざというときに、そういうところで力を出せるようなということも検討が必要なんじゃないかと思うんですけれども、ただ、事前にあらかじめ、そういうものというのが考えられていないと、なかなかそういう体制というのは難しいんじゃないかと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":49,"id":"exchange-019"},{"speaker":"大沢委員","kind":"質問","question":"学校避難所マニュアルなんですけれども、このマニュアルを読んでいると、ふだん学校で活躍されているＰＴＡという文言が出てこないんですけれども、被災時において、学校が避難所として使われるときに、ＰＴＡというのはどのような位置関係、どのような考え方を持って、これはまるっきり蚊帳の外であり、町会長が中心となった防災区民組織が中心となっていく、しかしながら。","respondent":"高山防災計画担当課長","answer":"したがいまして、委員ご指摘のそういった多様な方々の参画という点につきましては、当然のことながら、拒むものでもございませんし、むしろ、そういったことが進んでいくことが理想とは考えております。","voiceIndex":50,"id":"exchange-020","title":"町会・自治会支援"},{"speaker":"大沢委員","kind":"質問・要望","question":"そうすると、あくまでもＰＴＡの方たちは、避難所はボランタリーな位置関係にいるということで捉えてよろしいわけでしょうかね。もう１つ、教育委員会の方が来ているといったのでＰＴＡのことを聞いたんですけれども、もう１個、別のほうになってしまっていいですか。","respondent":"高山防災計画担当課長","answer":"現在のところは、いわゆる簡易トイレということで、室内で利用ができるトイレなどを中心に考えているところでございまして、そういった、いわゆる内部障害者の方に対するトイレ対策というのが必要な点については十分認識していますが、その取り組みとしては。","voiceIndex":52,"id":"exchange-021"},{"speaker":"大沢委員","kind":"意見","question":"むしろ、ここのところは内部障害の方が何人区内にいらっしゃるか、まして、各避難所に大体どれぐらいそういう方たちがいるのかという事前の数の把握ということは必要だと思うんですけれども、どのようにそこのところはお考えになっていますか。","respondent":"高山防災計画担当課長","answer":"そういった意味では、なかなか今回の計画の中にはその文言自体は反映されておりませんが、避難所ないしは災害時の医療の話し合いの中で、保健所などの内部の部門が参画して、この防災に関することに関しては知恵を出してくれているところですので、該当者の把握につきましては。","voiceIndex":54,"id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"今の大沢委員の関連なんですけれども、たしかオストメイトの方用の備蓄品の中で、パウチですか、これを調達する仕組みを品川区としてつくったということを、いわゆるそういうパウチを事前に置いておくのではなくて、業者に流通してもらうような仕組みをつくったということを、以前に聞いたことがあるんですけれども、それはありませんか。","respondent":"高山防災計画担当課長","answer":"そういう意味では、薬剤師会との間の医薬品の供給協定の中にはその品目はございませんでしたので、区として、いわゆる卸なり、そういった医療業界からの調達の仕組みは、現在のところはないと記憶しております。","voiceIndex":56,"id":"exchange-023"},{"speaker":"武内委員","kind":"意見","question":"以前、私がこれを取り上げたときに、前防災課長のときに、そういう仕組みを何かやったということの答弁があったんだよね。かえなきゃいけないから、ストマというか。だけれども、いざそれが足りなくなってしまったとき、避難所生活が長くなったときにということで、そういう仕組みをつくったということを以前、聞いたことがあるんだけれども、もう一回、もしなければ、つくってもらいたい。","respondent":"鈴木防災課長","answer":"関連しまして、現在も民間の事業者の方に災害時の協力をお願いする中で、衛生用品、包帯であるとか、医薬品以外の脱脂綿だとか、消毒関係、そういうものについて、今、ご協力をいただくような事業者の方とも相談をさせていただいていますので、そういう医療器具についても。","voiceIndex":58,"id":"exchange-024"},{"speaker":"武内委員","kind":"確認","question":"たしか人によってかえが合う、合わないがあるらしいんです。だから、事前に備蓄しておくことは難しいんだという、たしか当時、ご答弁があって、そういう方が避難してきたときに、そういうものを流通してもらうようなルートをつくる、もしくはつくったという話だったので、また確認してください。","respondent":"野呂瀬環境課長","answer":"当時、私は防災課の係長だったんですけれども、そういう話が出て、今、委員がおっしゃったとおり、個人によって差があるということも含めまして、今後、障害者福祉課等もいろいろ情報提供をしながら進めていくみたいなことで、多分、ご答弁したと思っていますので、今。","voiceIndex":60,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問","question":"生活のごみというのが、多分、大きな問題になってくるときに、学校としては、その先に教育施設として学校を再開したいというふうな思いが当然強いというところで、その置き場所というところが実際に考えているよりも大変なことになったときに、うまく連携がとれるのかなというところが心配なんですけれども、学校としては、ごみの置き場所とか、そういったところに何か課題があるというようなことはないのか。","respondent":"齋藤庶務課長","answer":"おそらく災害対策本部から、廃棄物の回収については、おおむねどの時点で回収の見通しが立つかという連絡を踏まえまして、地域の方、学校と相談して、場合によってはグラウンドに、物によっては衛生上問題であれば、穴を掘って埋めざるを得ない場合もあるかもしれませんし。","voiceIndex":62,"id":"exchange-026"},{"speaker":"井上委員","kind":"質問・要望","question":"そのケース・バイ・ケースでするということであれば、ぜひマニュアルのところにごみの表記も必ず入れていただきたいと思います。追記していくということだったので、組織図のほうにはごみの処理ということはあるんですけれども、それで柔軟に対応するんだということが、いつもそういうふうな連携がとれることが必要だと思うので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"平日の日中の普通に学校があるときに震災とか大災害が発生した場合、子どもたちは学校の担任の管理のもとにいるかと思うんですけれども、そこに今度、一般の避難者の方たちが来たときに、ずっと学校がそのまま子どもたちを、この間のときみたいに管理されているのか、それともどこかの段階で、一般の避難者と一緒に避難所運営会議のもとで子どもたちも普通の避難者と同じように管理というか。","respondent":"田村教育次長","answer":"実際にこれは統一して全校でやっているんですけれども、その中に、平常時での対応、それと、教育活動中に発生した場合、校外学習中に発生した場合、登下校中に発生した場合、夜間、週休日、休日に発生した場合、あと、先ほど庶務課長が言っていた３期休業、夏休みとか冬休み。","voiceIndex":65,"id":"exchange-028"},{"speaker":"沢田委員","kind":"質問","question":"別に子どもたちは、例えば親御さんが避難されてきたならば、親のところに戻すとか、そういうこともあるのかないのか、子どもたちは子どもたちでまとまってそこで避難していられるのか、そういう場合はどういうふうな状況になるんですか。","respondent":"田村教育次長","answer":"だけど、避難者が来たら、学校の施設管理者は学校長ですから、災害対策本部と逐次、今、避難所をまだ開設していないけれども、何人の避難者で、お年寄りが何名いるよと１時間単位に教育委員会に報告して、災害対策本部にも報告していますから。","voiceIndex":67,"id":"exchange-029"},{"speaker":"沢田委員","kind":"質問","question":"それはわかりました。その辺で、学校との関係がわかりました。それと別件なんですけれども、避難所連絡会議の中で開錠についてということで、校門、校舎の開錠のことで１点お聞きしたいんですけれども、この門をあけるかあけないかということの基準というか、災害が起きたときの何か決まりみたいなものはどういうふうな形になるんでしょうか。","respondent":"高山防災計画担当課長","answer":"学校避難所に参集する時間外の職員ですが、震度５弱のときに６km圏内の職員が参集することとなります。","voiceIndex":69,"id":"exchange-030"},{"speaker":"沢田委員","kind":"質問","question":"区だけじゃなくて、近隣の方も鍵を持っているかと思うんですけれども、そういった方たちに対しても、どういうふうな連絡体制で、例えば避難所連絡会議のメンバーじゃない方も、鍵を学校の近隣ということで町会の方とかで持たれている方がいるかと思うんですけれども、そういった方が、いざ震災等が起きたときに、どの段階で鍵をあけるのかということを。","respondent":"高山防災計画担当課長","answer":"基本的には、連絡がとれれば、もちろんそれで済んでしまう話だと思いますので、連絡がとれない前提に立ちますと、基本的には職員が参集するのが、都内においてそういった震度が発生した際ですので、基本的には鍵をお預けしているのは避難所連絡会議のメンバーの方々と。","voiceIndex":71,"id":"exchange-031"},{"speaker":"沢田委員","kind":"確認","question":"確認したいんですが、避難所連絡会議のメンバーじゃない方で鍵を持っていらっしゃる方はいらっしゃらないということですか。近隣の方とかで、学校の周りにお住まいの方で、町会長以外に近隣で持たれている方もいらっしゃると思ったんですけれども、そういうことはないんですか。","respondent":"高山防災計画担当課長","answer":"報告の中で、町会長以外で渡しているケースは、隣接する商店街の理事長に渡しているというケースは報告をいただいておりますが、それ以外に家が近いということだけでお渡ししているケースは、防災課への報告の中には入っておりません。","voiceIndex":73,"id":"exchange-032","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"質問","question":"今、沢田委員からも質問がありましたけれども、実際、鍵は何個ぐらいで、近隣の方がお持ちになっているのか、そして、今度は防犯のこととか、いろいろなことがあろうと思いますけれども、その数にもよりますけれども、それによって、そういう学校が、例えば防犯カメラをつけるとか、何か震災対策とはちょっと外れますけれども、そういうことが可能なのかどうか。","respondent":"鈴木防災課長、齋藤庶務課長","answer":"これは集まる町会が５つあるので、１本ずつで５本だということだと思いますが、基本的には各町会に１本ないしは２本をお渡しして、万が一のときには本部長、町会長か。古い学校もあるということです。記録したものも、機械のハードのものにもよりますけれども、１週間、あるいは１カ月保存できているです。","voiceIndex":75,"id":"exchange-033"},{"speaker":"木村委員","kind":"質問・要望","question":"そのようにして大震災が発生する時間帯にもいろいろよろうかと思いますけれども、学校は、例えば授業をやっている最中であれば何の問題もありませんけれども、これが、例えば真夜中であったり、夏休みだったりとか、いろいろな問題で、学校は大きな震災が起きてから避難所を開設するまでにはどれぐらいの時間を必要とするものなのか、わかれば教えていただきたいと思います。","respondent":"鈴木防災課長","answer":"先ほど教育次長からもお答えしましたように、本部の指示を待たないと開設できないというものではございませんので、避難所ごとに、状況に応じて、避難者の方が多数来ている場合には準備を始めて開設するということですので。","voiceIndex":78,"id":"exchange-034"},{"speaker":"木村委員","kind":"質問・要望","question":"ですから、一刻も早く、そういう意味では門をあけ、そしてグラウンドや、もしくは教室、そのときの天候によっても変わってくると思いますけれども、これが例えば大雨で大変寒いときであったら、一刻も早く教室とか、そういうところに避難させると思うんですけれども、先ほども、チェックをしなければならないというふうなことを言っておりましたけれども、そういう場合のことを考えて。","respondent":"鈴木防災課長、齋藤庶務課長","answer":"その場合には、状況に応じて臨機応変に、教育次長から説明したように、学校教職員、それから本部と連携をとりながら、できるだけ早い段階で区民の方の安全を確保できるように対応していきたいと考えて、また。学校の側でも、防災課長が申し上げましたとおり、迅速に対応できるように意識も変わっておりまして、用務主事や教職員もチェーンソーの訓練をするだとか、震災時にどういった対応をするのが十分なのかと議論しておりますので。","voiceIndex":80,"id":"exchange-035"},{"speaker":"高橋委員","kind":"確認","question":"校庭の壁とか、あと、古いバックネットとか、あと門柱とかでしょうか、そういうような非構造部材のほうの点検になるんでしょうか、ちょっとわかりませんけれども、そういったところの安全確認とその対応について、お尋ねします。","respondent":"齋藤庶務課長","answer":"ただ１個、万年塀だけは、共有のもの、相手方、持ち主との関係もありまして、計画的に進めておりますけれども、若干区の思いどおりにいかない部分もあって、その点だけは少し私どもとしても苦労しています。","voiceIndex":83,"id":"exchange-036"},{"speaker":"吉田委員","kind":"意見","question":"小学校、中学校の耐震化のところなんですけれども、いつ災害が起こるかわからないということで、起きてはほしくないんですけれども、例えば、御殿山小学校の平成２６年度完成予定でありますとか、あと、大間窪小学校の仮設のプレハブですとか、また清水台小学校のＢ１の補強工事中などということに関しての今の状況を、例えばこれもわが家の防災ハンドブックでは指定の学校避難所になっているんですけれども。","respondent":"田村教育次長","answer":"それと、御殿山小学校は一部あって、学校長はどこがＩｓ値０.７以上か全部知っていますから、避難の場所で、まだ若干平成２６年度まで時間かかりますけれども、どこがＩｓ値が幾つということは校長も当然、知っていますから、避難のときには。","voiceIndex":85,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"その辺に関して、何か困るようなことがあると、その辺の周知に関してはどうなっているのかと思ったんですけれども、それに関しても、指定避難所、ほかの学校とは変わらずにということで理解してよろしいでしょうか。","respondent":"田村教育次長","answer":"そのように理解してもらって結構です。","voiceIndex":87,"id":"exchange-038","title":"町会・自治会支援"}]},{"id":"topic-02","title":"を聴取したいと思います。 品川区地域防災計画（平成２４年度修正）素案","agenda":"を聴取したいと思います。 品川区地域防災計画（平成２４年度修正）素案","exchanges":[{"speaker":"渡辺委員","kind":"提案","question":"大変な取りまとめの情報量だったと思います。スケジュールを最後に説明いただきました。ただ、想定外という表現はあまり好きじゃないんですが、どうしても現場決裁、あるいは上位計画もある中での区での判断、現在、最善と想定していても、どう対応するかというものの弾力性というんですか、逆にこの計画が足かせにならないような対応策、この点の、総論ですが、考え方を教えていただければと思います。","respondent":"高山防災計画担当課長","answer":"そしてもう１つ、計画は必要であるけれどもということで、弾力性という部分、この辺についてはどうかですが、もちろん、上位計画との整合性の中で、また、災害対策基本法や災害救助法の中で決められている多くのそういった基本的な、全国的な基準はある一方で。","voiceIndex":94,"id":"exchange-039"},{"speaker":"渡辺委員","kind":"提案","question":"もう１点、今、内閣府から継続的な修正というご説明がありましたが、そうすると、時期も大体発行から１年後なのか、大体時期の目安だとか、そんな想定というか、時期はあるんでしょうか。","respondent":"高山防災計画担当課長","answer":"その内容を踏まえて、区としてもそれに遅れることなく、品川区地域防災計画も平成２５年度のある時点で、当然、見直していく必要があると考えておりますので、そういった意味では、今回、平成１９年度以来の修正と冒頭申しましたが、平成２４年修正で満足することなく。","voiceIndex":96,"id":"exchange-040"},{"speaker":"渡辺委員","kind":"質問","question":"これからの見通しがわかることで、今日も含めて、慌てることなく、また議会は議会のペースで、随時、提言なり質疑をしていこうと思います。これは議会も深く関わった素案のまとめだということで、これまでの時間が有意義だったと思うという解釈で、各論の質問はありませんので、明確なまた見直しのペースだとか、時期の目安がついたら、いち早くお知らせいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-041"},{"speaker":"阿久津委員","kind":"質問","question":"前回の委員会で飼育動物について、正副委員長の温かいご配慮と、また、委員会の皆様の温かいご理解をいただいて、中間まとめの中に入れていただいて、今日は、全部読み込めたわけじゃないんですけれども、見ましたら、前回のものと比べると、かなりの記載があると思うんですけれども、まず最初に、ペットの管理についてということで、動物の保護というところで、どう大きく変わったのかだけ。","respondent":"高山防災計画担当課長","answer":"それについては区としても賛同するところでございまして、その上で、当然、家族も同然ということでのペットの災害時の考え方なんですが、基本的には平時のしつけであるとか、ペットフードの備蓄なども細かくは、これは飼い主の責務だと思います。","voiceIndex":99,"id":"exchange-042"},{"speaker":"阿久津委員","kind":"質問・要望","question":"いざ避難所にこういうものをつくりますよということが計画に載ったけれども、うちの避難所はこういうことはできないよというふうに避難所連絡会議で決まってしまったよなんていうことがないように、ここのところは、要望も含めて、そこら辺の考え方を伺いたいと思います。","respondent":"高山防災計画担当課長","answer":"必ずしも域内で難しいということであれば、域外も含めた広域的な調整というようなことに関しましては、災害時のペット以外でも、今回の都の地域防災計画でも特に目立つポイントだと思いますので、品川区内ですべてが完結するということではなく、そういった広域的な調整も含めて。","voiceIndex":101,"id":"exchange-043"},{"speaker":"阿久津委員","kind":"質問・要望","question":"ぜひ柔軟な対応をとっていただきたいと思います。こういうことがせっかく、今、進んできているので、これをどこまで自治体がやる責任があるんだと言われてしまうと、なかなかそれはペットのあれだということもあるかもしれませんけれども、例えば獣医師会等とも協力をして、そういう機会を持っていただいて、ぜひペットの飼い主に対しても周知をお願いしたいと思うんですが、いかがでしょうか。","respondent":"高山防災計画担当課長","answer":"獣医師会との連携というお話ですが、実はそういった会合にも参加させていただいたことがありまして、そういった区の取り組みにつきましては獣医師会としても協力したいというようなことをおっしゃっていただいておりますので、そういった意味では。","voiceIndex":103,"id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"昨年の３・１１で、東日本大震災で２万人近い方が犠牲になられるという大きな災害の後での初めての地域防災計画の見直しということになるわけですけれども、私はあの教訓を最大限活かして、大都市のスーパー災害、今、巨大地震が起こったら、東京でスーパー災害が起こるだろうと言われているわけですけれども。","respondent":"高山防災計画担当課長","answer":"地域防災計画もそうなんですが、国の基本となる防災基本計画も、予防段階で取り組むべき事項、そして災害直後の応急対応、そして復旧・復興というような形で、それぞれにおいて必要なことについて計画を立てているところです。","voiceIndex":106,"id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"まず初歩的な、基本的なところでお伺いしたいのが、記載の仕方なんですが、第１部、第２部、第３部ということで、東京都地域防災計画を見ましたら、第２部の何章とかというところまでこの黒い脇に書いてあるところに書かれていて、どこに書いてあるのかというふうなところを目次から見ていくときにすごくわかりやすい、そういう表示になっていたので、どこにどう書いてあるのかということが、今までの計画と。","respondent":"高山防災計画担当課長","answer":"しかしながら、目次のボリュームが増すことで、また見にくくなるといったこともございまして、基本的には、これに索引を、もちろん最終的にはつけするということが１つと、もう１つは、先ほどご説明申しました中で、それぞれのしかるべき編で。","voiceIndex":108,"id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"実際、どこまでいっているのかわかりません。結局、地震になりました。変わりませんということにもなりかねないと思うんですね。やはり、これを実効性あるものにするというところでは、そこら辺の具体化というのがすごく大事になってくるんじゃないかなと思うんですけれども、その点はいかがでしょうか。","respondent":"高山防災計画担当課長","answer":"そういったものも１つ情報としながら、先ほどの都の担当者からの聞き取りなども踏まえて、より数値目標を達成していく上での具体の施策というのが、どのような計画段階で想定できるのかということに関しましては、先ほどの繰り返しになりますが、本案の作成に向けて。","voiceIndex":110,"id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ここの減災目標のところで、ちょっとよくわからなかったのが、目標２のところでの「中枢機能を支える機関の機能停止を回避する」「企業等の」云々と書かれているんですけれども、その目標達成するための主な施策で、自衛隊等との連携強化を含めた危機管理体制の充実というのが入ってくるんですけれども。","respondent":"高山防災計画担当課長","answer":"東京都においても、これまで３０日かかると言われている上水道の復旧を、２０日に縮めるべく努力をしているという話を聞いておりますので、それはまさに予防対策そのものではないかと思う一方で、一たび寸断してしまった際には、それを早期に修復するといった点も。","voiceIndex":112,"id":"exchange-048"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、どこにあるんだろうということでずっと見ていましたら、耐震化というのが７４ページのところで、民間建築物の安全化の中の１という項目の中で出てきたんですけれども、前は、たしか章というところで耐震化というのが位置づけられていましたので、きちんと目次の中にも出てきていたんですけれども、目次の中から耐震化というのが消えてしまいましたし、こういう対策の視点の中にも。","respondent":"高山防災計画担当課長","answer":"要は、１つ、テーマとして統合していく中で、こういった扱いといいますか、上下関係ということでもないんですが、目次上、このような整理をさせていただいたというだけでございまして、決して区としての取り組みに何ら後退するものがあるということではございません。","voiceIndex":114,"id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だけど、やはり耐震化なしに予防、対策というのはあり得ないと思うんですよね。そういう点で言えば、後退しないということであれば、私は耐震化というのを、しっかりとこの地域防災計画の中に言葉として明記をしていただきたいと。そして、取り組みも進めていただきたいと思うんですけれども、いかがでしょうか。","respondent":"高山防災計画担当課長","answer":"計画の減災目標の中に、耐震化という文言が出てくるべきではないかという点につきましては、先ほどのお話の中でもさせていただきました、具体的な取り組みの１つとして、そういったものを対策の１つとしてうたうということについては、当然のことながら。","voiceIndex":116,"id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"違う中身です。これを、地域別にまとめていただくと、この地域にどれぐらいあるかというのがわかりやすいかなと思ったので、そこら辺のところを具体的に、ちょっと細かい点なんですけれども、お願いできたらなと思っていますが、いかがでしょうか。","respondent":"高山防災計画担当課長","answer":"何かこの方法が一番いいという表というのも、結果としてはないのかと思いますが、現時点ではこのような形で、整備年度を中心とした表ということで、今回の素案は提出させていただいているところです。","voiceIndex":118,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちょっとまた細かいところなんですが、９９ページの密集市街地整備促進事業なんですけれども、今４地域がこういう形で取り組まれているんですが、私はこういう密集市街地の取り組みというのは、本当に地域に根差して、区の職員の方も来ていただいて、地域の方の声も聞いていただいて、とても丁寧でいい取り組みだなと思っているんですけれども、まだまだ同じような木造密集地域というのは。","respondent":"品川防災整備担当課長","answer":"ですので、やはり事業的にかなり時間がかかるということもありまして、まずは災害防災的にも改善しなければいけない地域を優先して、現在行っているようなものです。この辺の成果の状況を見て、またほかの地区ということになってくるという考えです。","voiceIndex":120,"id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ゆっくりではあるんですけれども、確実に公園ができたりとか、道幅が広がっていったりとか、そういうところではすごく地域にとっては喜ばれているんですよね。では、その隣の町会が安全かといえば、全然同じような状況でして、そこのところは、１つも公園がなくても、なかなか区単独では公園をつくることができないという矛盾もありますので、ぜひ拡大ということで取り組んでいただけたらと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-053"},{"speaker":"井上委員","kind":"質問","question":"４３ページの地域防災訓練のところで、今回は女性の視点とか、子どもとか、弱者というところで、新たに改善をしたテーマで大変評価はされるんですけれども、この丸の３つ目のところに、「女性が気軽に参加できる訓練の実施」という一段なんですけれども、ここにやはり「災害弱者当事者の訓練」というものも、助けていただくだけの方たちではないと思っていますので。","respondent":"鈴木防災課長、高山防災計画担当課長","answer":"現在は、その中身がまだ確定していない段階ですので、現状のものを暫定的に書かせていただいているですので、今後の予算編成作業、それから、実際の検討にあわせて、内容の表記は変更の予定をしております。それだけにとどまらず、内部においても、引き続き文言等については、先ほどの品川シアターの活用なども含めまして、ぎりぎりのタイミングまで、ここに限らず、内容についての見直しは図ってまいりますので。","voiceIndex":123,"id":"exchange-054"},{"speaker":"井上委員","kind":"質問・要望","question":"次、１９５ページで、前の震災対策特別委員会でも発災地避難所においてのボランティアとの連携というところで、他自治体からのボランティアの振り分けとか、そういったところを綿密にやっておく必要があるということで、ここにも「体制整備を図る」という表記になっているんですが、ほかのところにも、これをもとに体制を整えるとか、これから詳しくしていきましょうという表記があると思うんですけれども。","respondent":"高山防災計画担当課長","answer":"そんな中で、例えばボランティアにつきましては、実は東京都生活文化局がボランティアについての見直しをしておりまして、基本的には生活文化局の役割が後退して、市区町村の役割がより重くなるという形での見直しというか、区側からすれば改悪のような形になってしまうんですが。","voiceIndex":126,"id":"exchange-055"},{"speaker":"井上委員","kind":"質問","question":"実際には、この対策が機能しなくなるようになればいいなと私は考えているんですが、その中で、３８２ページの放射線等使用施設の応急措置という第２節第２の部分があるんですけれども、これは想定として、品川区には放射性物質を扱っている施設がないということが前提にあると思うんですが、これは原子力発電所をイメージしているのか、その中で住民の避難誘導とか、避難所の開設とか、ここの部分というのは。","respondent":"高山防災計画担当課長","answer":"災害につきましては、基本的には品川区内の災害というよりは、遠隔地での災害ということを基本的には前提とした対応策の構成となっているところです。","voiceIndex":128,"id":"exchange-056"},{"speaker":"井上委員","kind":"質問・要望","question":"これは、区民の求めに応じというよりも、区の責任でそういうことをするという表記のほうが積極的だし、被ばく線量というのは身体的なものなのか、食品についてはなかなか都の管理というのもあるんですけれども、区も主体的に、今は学校給食のみなんですけれども、いろいろな問題があったときに、区としてそういう食料品の被ばく線量、放射線量まで、こういったところでイメージされているのか。","respondent":"高山防災計画担当課長、野呂瀬環境課長","answer":"もう一つ、被ばく線量の測定の実施につきましては、災害の規模などにもよりますが、その時々の判断ということでございまして、現段階で食材まで含めて、区の責務で対応していくというところの判断というのは。こういう防災対策に書かれていることも、これは今後、区ができることで、区民の皆様の不安を払拭するためのことは必要に応じて暫時やっていくと、この考えに変わりはございません。","voiceIndex":130,"id":"exchange-057"},{"speaker":"武内委員","kind":"質問","question":"この後、パブリックコメントが１２月１２日から始まるということなんですが、そうすると、これをもう一度、誤字脱字も含めて、パブリックコメントをかける前に、見直してチェックをするということはやられるんでしょうか。","respondent":"高山防災計画担当課長","answer":"パブリックコメントをする前段階として、もう一度校正を入れます。ですので、仮にその段階で発見されたものについては対応するものです。","voiceIndex":133,"id":"exchange-058"},{"speaker":"武内委員","kind":"質問","question":"たまたま、今見ていて、例えば２３ページの目標１のところの下のほうで、「目標を達成するための主な対策」と、３つある中の２番目の「木造地域不燃化１０年プロジェクト」とありますね。これは「木密」ではないのかと。「木密地域不燃化１０年プロジェクト」ではないのかと思うんだけれども、いかがでしょうか。","respondent":"高山防災計画担当課長","answer":"速やかに対応します。","voiceIndex":135,"id":"exchange-059"},{"speaker":"武内委員","kind":"質問・要望","question":"これは、要望で結構です。それで、あと、質問としては、今ここに本冊がありますけれども、前は別冊資料というのをいただいています。そうすると、この別冊資料のほうも、例えば本冊にあわせて追補みたいな形でやるのか、また新しいものをつくっていただけるのか。もしつくるとすれば、スケジュール的にどんな感じで考えているのか、教えてください。","respondent":"高山防災計画担当課長","answer":"時期的なものにつきましては、２月の防災会議に、風水害編とあわせて、別冊ともども会議に付議いたしまして、ご承認をいただくといったスケジュールで進めてまいりたいと考えております。","voiceIndex":137,"id":"exchange-060"},{"speaker":"武内委員","kind":"質問","question":"それで、今回１万人強増えましたよと。物理的に無理ならしようがないんですけれども、やはり民間とか、そういうところにまた避難所の、今は協定なんかをマンションとやっていますけれども、追いつくかどうかというのもありますけれども、それがこの２月までの期間で１万数千の数を確保しようと考えているのか、それとも、それはそれということなのか、そこをちょっと教えてください。","respondent":"高山防災計画担当課長","answer":"あるいは、地域も含めた対応ということを考えていきますと、都内での対応ということも当然視野に入れて、品川区民の中の被災者を受け入れていくということは、広域的な域外被害という、地域外の被害というような対応も、今回の都の考え方にも。","voiceIndex":139,"id":"exchange-061"},{"speaker":"武内委員","kind":"質問","question":"そうすると、ただでさえ品川区の中で、私はここの避難所になっているけれども、場所的にはこっちのほうが近いんだという話が出るぐらいの中で、例えば、ある地域は避難所が足りないから、では、隣の区のこういう施設に行ってくださいねということになる。東京都はそこまで考えている。品川区も、それを今、場合によっては検討すると、こういうことでよろしいですか。","respondent":"高山防災計画担当課長","answer":"そういったものについては、オール東京都といいますか、東京都全体で立ち向かうということが基本的な東京都の考え方ですし、都を初めとした他の都道府県についても、そのような考え方で計画するものですので、ご自宅により近い避難所での生活というのは。","voiceIndex":141,"id":"exchange-062"},{"speaker":"武内委員","kind":"質問","question":"ぜひそれは早目に。もし品川区が、さっき言った、今使っていないほかの施設も活用する、また民間との協定も進めていく。計画上かもしれないけれども、早目にご理解いただかなければいけないと思うので、また我々の委員会にもご報告いただきながら、早目にやっていかなければいけないのかなと思いますけれども、どうですか。","respondent":"高山防災計画担当課長","answer":"冒頭のほうに出てまいりましたように、地域防災計画は、今回修正して、また次なる修正が何年か後ということではなく、順次改訂していく中で、避難施設としてふさわしい施設が順次確保できた時点で積み増していくような形で。","voiceIndex":143,"id":"exchange-063"},{"speaker":"向委員","kind":"質問・要望","question":"というのが、目次とか、こういうところは、本当に数ページしかなくて、重要なキーワードはかなりたくさんあると思うんですけれども、例えばライフラインについて知りたいといっても、では、ライフラインがどこに書いてあるのかなとなると、大きな項目とかは書いてあって、そのページごとに対応テーマとかも、今回新しく、対応テーマが第１章に何が書いてあるとかはわかりやすく。","respondent":"高山防災計画担当課長","answer":"前回の平成１９年版と比べまして、いろいろと新しい考え方なども取り入れながら、見方についてはいろいろ工夫はさせていただいたと自負していますし、先ほど委員のほうからも、テーマや字句の説明が冒頭にあっていいというお話もいただいております。","voiceIndex":145,"id":"exchange-064"},{"speaker":"向委員","kind":"質問・要望","question":"やはり、今みたいに情報化社会になってきて、これが例えばＣＤ－ＲＯＭとか、パッドシステム上で検索できると、単語を入れればヒットするんですけれども、紙になるとそのあたりができないと。なので、そこら辺を、この計画を手にとった皆さんが、欲しい情報をできるだけ早目にとれるような工夫を、あと数カ月ですけれども、お忙しい中、検討していただけたらということで、要望で終わります。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-065"},{"speaker":"南委員長","kind":"質問・要望","question":"なければ以上で終了していきたいと思いますけれども、私から、ちょっと最後に一、二、確認させていただきたいと思っていますが、これだけのものができてきているんですが、各所管で検討していただいたものを積み上げてまとめたという認識でいいんでしょうか。１番目のことだけ、お願いいたします。","respondent":"高山防災計画担当課長","answer":"今回につきましては、震災後ということで、その時点の修正にとどまらず、庁内的な議論を酌み交わそうということで、区役所の内部におきましては、いわゆる分科会のような形式で、テーマごとに検討する場を持ちました。","voiceIndex":149,"id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6422#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":76079,"voices":155}},{"id":"h24-20121207-9","meetingId":"h24-cm12","date":"2012年12月7日","dateIso":"2012-12-07","committee":"文教委員会","time":"午後１時３５分～午後１時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"確認","question":"わかりましたということなんですけれども、説明的にはね。それと、今の説明を聞いて、改めて私は再認識したんですけれども、学校教育職員のこの給与に関する条例というのは、独自採用の教員の給料に関する条例というふうに認識をしていくということが今、改めて再度確認されましたので、そういうことで見ておきたいと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"確認","question":"内容の確認させてください。こちらの資料、指導課の資料で、公民較差０.１９％解消するという表現になっていて、１０ページの資料だと公民較差０.３２％となっているんですよ。このことは、なぜ差異があるのかということが１点と、それから、住居手当の見直しをすると同時に、生じた減額分を加算するという、そういうややこしいことを何でするのかなという素直な疑問なんですが。","respondent":"太田指導課長","answer":"０.１９％のマイナスということと、１０ページの資料につきましては、第９１号議案のほうの給料表がわかりにくかったものですから、第９１号議案のほうの給料表の比較を載せしています。ちょっと説明が至らなくて申しわけございません。","voiceIndex":8,"id":"exchange-002"},{"speaker":"阿部委員","kind":"質問","question":"今の話の中で、住居手当、持家の方にも、つまりこれまでは払っていたということなんですよね。民間にいたときに、そういう発想は全くなかったんですけれども、それは全国一律で、教員および公務員の場合はそのような感じになっていて、今回初めて住宅手当が見直されたという経過でよろしいんでしょうか。","respondent":"太田指導課長","answer":"国のほうでは、平成２１年度以降、全面的に住居手当についてはなくしております。それを追随するというか、それに倣うということで、今回、東京都の人事委員会のほうが住居手当の見直しを図ったです。","voiceIndex":10,"id":"exchange-003"},{"speaker":"阿部委員","kind":"質問","question":"この住居手当見直しの減額分を補完するという時限的な措置なんですか。それとも、もう給料表として恒久的に措置するということなのか。","respondent":"田村教育次長","answer":"恒久的な制度です。それで、先ほど指導課長から説明したように、もともと１０ページの4)と5)の間を見てもらうと、住居手当は、国は持家に係る住居手当を廃止済みです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"渡部副委員長","kind":"確認","question":"今の話を聞いていて、であれば、そうかそうかでないかだけの確認なんですけれども、例えば４０歳の先生がいます。同じ学校に都の採用、区の採用といった場合、給与は都に合わせると言いつつ、住宅手当の部分で、教員の方は、特別区人事委員会のほうが住宅手当に手をつけない限り、給与を余計にもらってしまうよというような形が今でき上がるということでしょうか。","respondent":"太田指導課長","answer":"そのとおりです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"高橋委員","kind":"意見","question":"要するに、3)にあるように、諸手当は行政の方と同じなんですよね、都の職員は。ところが、区費の先生方は、この手当でやっているので、恐らく、今、住宅手当の話が出ましたけれども、期末勤勉手当のところで差が出てくるのではないかなと思っているんですけれども、もし、今数字があれでしたら後ほどで結構です。","respondent":"田村教育次長","answer":"後で、細かい数字は後ほど。","voiceIndex":16,"id":"exchange-006"},{"speaker":"南委員","kind":"意見","question":"賛成はするんですけれども、先ほど申し上げましたように、限りなく、やはりこのままでいったら不況が続く、所得が減って購買力が落ちるという点ではいかがなものかと思います。しかし、人勧でそういう勧告を出したという制度上でやむを得ないというふうには思っておりますけれども、一日でも早くそういう状況から脱出をしていくことが必要なのではないかというふうには思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4780#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":5831,"voices":29}},{"id":"h24-20121207-5","meetingId":"h24-cm12","date":"2012年12月7日","dateIso":"2012-12-07","committee":"総務委員会","time":"午後１時３６分～午後１時４８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第８９号議案 職員の給与に関する条例の一部を改正する条例","agenda":"第８９号議案 職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"前回の１１月の折に、給料表のところではなく、諸手当のことで、今後の検討課題であるというご答弁があったんですが、それと諸手当のところと、この間、何年ぐらいずっと引き下げが行われているのかなというあたりも教えてください。","respondent":"堀越人事課長","answer":"諸手当の部分ですけれども、具体的には、今後の住居手当制度のあり方につきまして、特別区の実情ですとか、ほかの団体の状況等見ながら、検討していく必要があるという形で意見が出されているところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"国の段階とか、あと、東京都のところでいろいろ変化が起きているんですけれども、この辺の待遇的なものがどうなのかというのを教えていただきたいのと、引き下げの状況が１０年間で６回引き下げがあったということで、かなり今後のことについて影響があるかなと思うところは、年金とか退職金なんかにもかなり影響するんでしょうか。そういうところ、雑駁でいいので教えていただきたい。","respondent":"堀越人事課長","answer":"見直しの検討の時期ですけれども、人事委員会のほうでも意見が出ておりますので、他団体の状況を見ながら、時期を失することなく、検討していくという形になると思います。具体的な時期については、まだ具体的なものは出てきていないという状況です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"住宅手当が、国のあたりの持ち家制度だとかが廃止されるという方向で、意見を聞いてみると、やはり今持ち家で住宅ローンとかを抱えていて、働き盛りのところですごく将来不安だという声もあったりするので、今後のことではあると思うんですけれども、十分、状況で判断してほしいなと思ったのが１点と、やはりたび重なる引き下げという面では。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1934#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":3805,"voices":20}}]);
